-- =====================================================================================
-- Service Intelligence — Phase 1, step 2: profile the phase-1 tables (AGGREGATE-ONLY)
-- Generated; every query returns counts, percentages, min/max or value counts — never rows.
-- Sensitive columns (names, location, CUSTOM_FIELD) get a null rate only: no values, no min/max.
--
-- Run as DEV_ADMIN on DEVELOPMENT_WH (X-Small is enough; Q01, Q08–Q10 and Q14 scan the
-- largest tables and take a few minutes each). Each query is one statement and returns one
-- result set; export each result (Download → CSV) or run them through the Claude connector.
--
--   Q01–Q10  one per table: rows, duplicates (candidate key and whole row), null/blank rate
--            per column, text→timestamp and text→number conversion rates, min/max, freshness
--   Q11      telemetry monthly volume by event time (coverage and gaps)
--   Q12      OLGA snapshots (rows and value per END_OF_MONTH / YEAR_MONTH)
--   Q13      value counts of units, flags, levels and dealer codes
--   Q14      serial-number match rates: telemetry ↔ OLGA ↔ MANDL_CDM_PROD.MANCDM.SERVICEORDER
--   Q15      dealer, customer and opportunity-key match rates
--   Q16–Q17  Helios service orders: coverage, freshness, nulls, statuses
--
-- Duplicate keys use COUNT(DISTINCT HASH(...)) so rows with a null key column still count.
-- Soft-deleted service orders (ROWOPERATION = 'DELETE') are excluded from the match rates (Q14).
--
-- Conversion uses TRY_TO_TIMESTAMP_NTZ / TRY_TO_DOUBLE with AUTO format. Note that AUTO reads
-- an all-digit string (e.g. '202510') as seconds since 1970, so check raw_min/raw_max next to
-- the converted min/max before trusting a conversion rate.
-- =====================================================================================

USE ROLE DEV_ADMIN;
USE WAREHOUSE DEVELOPMENT_WH;

-- Q01  DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY
SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(MESSAGE_ID, ASSET_SERIAL_NUMBER, FAULT_ECU_ID, SPN_CODE, FMI_CODE, CID_CODE, EID_CODE, OCCURRENCE_DATETIME))), '(null)') AS "distinct_key|MESSAGE_ID+ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(MESSAGE_ID, ASSET_SERIAL_NUMBER, FAULT_ECU_ID, SPN_CODE, FMI_CODE, CID_CODE, EID_CODE, OCCURRENCE_DATETIME))), '(null)') AS "duplicate_key_rows|MESSAGE_ID+ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "distinct_serials|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_min|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_max|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MESSAGE_ID IS NULL OR TRIM(MESSAGE_ID) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MESSAGE_ID",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_SERIAL_NUMBER IS NULL OR TRIM(ASSET_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(STANDARD_MANUFACTURER_CODE IS NULL OR TRIM(STANDARD_MANUFACTURER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|STANDARD_MANUFACTURER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_MODEL_AND_MODIFIER_NUMBER IS NULL OR TRIM(SALES_MODEL_AND_MODIFIER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_MODEL_AND_MODIFIER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_ALTERNATE_NAME IS NULL OR TRIM(ASSET_ALTERNATE_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_ALTERNATE_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEVICE_SERIAL_NUMBER IS NULL OR TRIM(DEVICE_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEVICE_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MODULE_DATETIME IS NULL OR TRIM(MODULE_DATETIME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(MODULE_DATETIME), ''))), '(null)') AS "raw_min|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(MODULE_DATETIME), ''))), '(null)') AS "raw_max|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(MODULE_DATETIME), '')))), '(null)') AS "raw_len_min|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(MODULE_DATETIME), '')))), '(null)') AS "raw_len_max|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(MODULE_DATETIME)))) / NULLIF(COUNT_IF(NULLIF(TRIM(MODULE_DATETIME), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(MODULE_DATETIME)))), '(null)') AS "to_timestamp_min|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(MODULE_DATETIME)))), '(null)') AS "to_timestamp_max|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(MODULE_DATETIME)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(MODULE_DATETIME)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|MODULE_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RECEIVED_DATETIME IS NULL OR TRIM(RECEIVED_DATETIME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(RECEIVED_DATETIME), ''))), '(null)') AS "raw_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(RECEIVED_DATETIME), ''))), '(null)') AS "raw_max|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(RECEIVED_DATETIME), '')))), '(null)') AS "raw_len_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(RECEIVED_DATETIME), '')))), '(null)') AS "raw_len_max|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))) / NULLIF(COUNT_IF(NULLIF(TRIM(RECEIVED_DATETIME), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))), '(null)') AS "to_timestamp_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))), '(null)') AS "to_timestamp_max|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(EQUIPMENT_OWNER IS NULL OR TRIM(EQUIPMENT_OWNER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|EQUIPMENT_OWNER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(NUMBER_OF_DIAGNOSTICS IS NULL OR TRIM(NUMBER_OF_DIAGNOSTICS) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|NUMBER_OF_DIAGNOSTICS",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_DOUBLE(TRIM(NUMBER_OF_DIAGNOSTICS)))) / NULLIF(COUNT_IF(NULLIF(TRIM(NUMBER_OF_DIAGNOSTICS), '') IS NOT NULL), 0), 2)), '(null)') AS "to_number_ok_pct|NUMBER_OF_DIAGNOSTICS",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_DOUBLE(TRIM(NUMBER_OF_DIAGNOSTICS)))), '(null)') AS "to_number_min|NUMBER_OF_DIAGNOSTICS",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_DOUBLE(TRIM(NUMBER_OF_DIAGNOSTICS)))), '(null)') AS "to_number_max|NUMBER_OF_DIAGNOSTICS",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_DOUBLE(TRIM(NUMBER_OF_DIAGNOSTICS)) < 0)), '(null)') AS "to_number_negative_rows|NUMBER_OF_DIAGNOSTICS",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LEVEL IS NULL OR TRIM(LEVEL) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|LEVEL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FAULT_ECU_ID IS NULL OR TRIM(FAULT_ECU_ID) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FAULT_ECU_ID",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SPN_CODE IS NULL OR TRIM(SPN_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SPN_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(EID_CODE IS NULL OR TRIM(EID_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|EID_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FMI_CODE IS NULL OR TRIM(FMI_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FMI_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CID_CODE IS NULL OR TRIM(CID_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CID_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FAULT_TYPE_CODE IS NULL OR TRIM(FAULT_TYPE_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FAULT_TYPE_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DESCRIPTION IS NULL OR TRIM(DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OCCURRENCE_COUNT IS NULL OR TRIM(OCCURRENCE_COUNT) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OCCURRENCE_COUNT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_DOUBLE(TRIM(OCCURRENCE_COUNT)))) / NULLIF(COUNT_IF(NULLIF(TRIM(OCCURRENCE_COUNT), '') IS NOT NULL), 0), 2)), '(null)') AS "to_number_ok_pct|OCCURRENCE_COUNT",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_DOUBLE(TRIM(OCCURRENCE_COUNT)))), '(null)') AS "to_number_min|OCCURRENCE_COUNT",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_DOUBLE(TRIM(OCCURRENCE_COUNT)))), '(null)') AS "to_number_max|OCCURRENCE_COUNT",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_DOUBLE(TRIM(OCCURRENCE_COUNT)) < 0)), '(null)') AS "to_number_negative_rows|OCCURRENCE_COUNT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OCCURRENCE_DATETIME IS NULL OR TRIM(OCCURRENCE_DATETIME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(OCCURRENCE_DATETIME), ''))), '(null)') AS "raw_min|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(OCCURRENCE_DATETIME), ''))), '(null)') AS "raw_max|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(OCCURRENCE_DATETIME), '')))), '(null)') AS "raw_len_min|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(OCCURRENCE_DATETIME), '')))), '(null)') AS "raw_len_max|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)))) / NULLIF(COUNT_IF(NULLIF(TRIM(OCCURRENCE_DATETIME), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)))), '(null)') AS "to_timestamp_min|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)))), '(null)') AS "to_timestamp_max|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(REFRESH_TIMESTAMP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|REFRESH_TIMESTAMP",
    COALESCE(TO_VARCHAR(MIN(REFRESH_TIMESTAMP)), '(null)') AS "min|REFRESH_TIMESTAMP",
    COALESCE(TO_VARCHAR(MAX(REFRESH_TIMESTAMP)), '(null)') AS "max|REFRESH_TIMESTAMP",
    COALESCE(TO_VARCHAR(DATEDIFF('hour', MAX(REFRESH_TIMESTAMP), CURRENT_TIMESTAMP())), '(null)') AS "hours_since_max|REFRESH_TIMESTAMP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LAST_UPDATE_TIMESTAMP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MIN(LAST_UPDATE_TIMESTAMP)), '(null)') AS "min|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MAX(LAST_UPDATE_TIMESTAMP)), '(null)') AS "max|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(DATEDIFF('hour', MAX(LAST_UPDATE_TIMESTAMP), CURRENT_TIMESTAMP())), '(null)') AS "hours_since_max|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE IS NULL OR TRIM(DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NAME IS NULL OR TRIM(CUSTOMER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRIMARY_CUSTOMER_IDENTIFIER IS NULL OR TRIM(PRIMARY_CUSTOMER_IDENTIFIER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRIMARY_CUSTOMER_IDENTIFIER"
  FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|MESSAGE_ID+ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME", "duplicate_key_rows|MESSAGE_ID+ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME", "distinct_full_rows|*", "duplicate_full_rows|*", "distinct_serials|ASSET_SERIAL_NUMBER", "serial_len_min|ASSET_SERIAL_NUMBER", "serial_len_max|ASSET_SERIAL_NUMBER", "null_or_blank_pct|MESSAGE_ID", "null_or_blank_pct|ASSET_SERIAL_NUMBER", "null_or_blank_pct|STANDARD_MANUFACTURER_CODE", "null_or_blank_pct|SALES_MODEL_AND_MODIFIER_NUMBER", "null_or_blank_pct|ASSET_ALTERNATE_NAME", "null_or_blank_pct|DEVICE_SERIAL_NUMBER", "null_or_blank_pct|MODULE_DATETIME", "raw_min|MODULE_DATETIME", "raw_max|MODULE_DATETIME", "raw_len_min|MODULE_DATETIME", "raw_len_max|MODULE_DATETIME", "to_timestamp_ok_pct|MODULE_DATETIME", "to_timestamp_min|MODULE_DATETIME", "to_timestamp_max|MODULE_DATETIME", "to_timestamp_future_rows|MODULE_DATETIME", "to_timestamp_before_2000_rows|MODULE_DATETIME", "null_or_blank_pct|RECEIVED_DATETIME", "raw_min|RECEIVED_DATETIME", "raw_max|RECEIVED_DATETIME", "raw_len_min|RECEIVED_DATETIME", "raw_len_max|RECEIVED_DATETIME", "to_timestamp_ok_pct|RECEIVED_DATETIME", "to_timestamp_min|RECEIVED_DATETIME", "to_timestamp_max|RECEIVED_DATETIME", "to_timestamp_future_rows|RECEIVED_DATETIME", "to_timestamp_before_2000_rows|RECEIVED_DATETIME", "null_or_blank_pct|EQUIPMENT_OWNER", "null_or_blank_pct|NUMBER_OF_DIAGNOSTICS", "to_number_ok_pct|NUMBER_OF_DIAGNOSTICS", "to_number_min|NUMBER_OF_DIAGNOSTICS", "to_number_max|NUMBER_OF_DIAGNOSTICS", "to_number_negative_rows|NUMBER_OF_DIAGNOSTICS", "null_or_blank_pct|LEVEL", "null_or_blank_pct|FAULT_ECU_ID", "null_or_blank_pct|SPN_CODE", "null_or_blank_pct|EID_CODE", "null_or_blank_pct|FMI_CODE", "null_or_blank_pct|CID_CODE", "null_or_blank_pct|FAULT_TYPE_CODE", "null_or_blank_pct|DESCRIPTION", "null_or_blank_pct|OCCURRENCE_COUNT", "to_number_ok_pct|OCCURRENCE_COUNT", "to_number_min|OCCURRENCE_COUNT", "to_number_max|OCCURRENCE_COUNT", "to_number_negative_rows|OCCURRENCE_COUNT", "null_or_blank_pct|OCCURRENCE_DATETIME", "raw_min|OCCURRENCE_DATETIME", "raw_max|OCCURRENCE_DATETIME", "raw_len_min|OCCURRENCE_DATETIME", "raw_len_max|OCCURRENCE_DATETIME", "to_timestamp_ok_pct|OCCURRENCE_DATETIME", "to_timestamp_min|OCCURRENCE_DATETIME", "to_timestamp_max|OCCURRENCE_DATETIME", "to_timestamp_future_rows|OCCURRENCE_DATETIME", "to_timestamp_before_2000_rows|OCCURRENCE_DATETIME", "null_pct|REFRESH_TIMESTAMP", "min|REFRESH_TIMESTAMP", "max|REFRESH_TIMESTAMP", "hours_since_max|REFRESH_TIMESTAMP", "null_pct|LAST_UPDATE_TIMESTAMP", "min|LAST_UPDATE_TIMESTAMP", "max|LAST_UPDATE_TIMESTAMP", "hours_since_max|LAST_UPDATE_TIMESTAMP", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|CUSTOMER_NAME", "null_or_blank_pct|PRIMARY_CUSTOMER_IDENTIFIER"));

-- Q02  DOMAIN_TELEMETRY.FAULT_CODE_HISTORY
SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_HISTORY' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(ASSET_SERIAL_NUMBER, FAULT_ECU_ID, SPN_CODE, FMI_CODE, CID_CODE, EID_CODE, OCCURRENCE_DATETIME))), '(null)') AS "distinct_key|ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(ASSET_SERIAL_NUMBER, FAULT_ECU_ID, SPN_CODE, FMI_CODE, CID_CODE, EID_CODE, OCCURRENCE_DATETIME))), '(null)') AS "duplicate_key_rows|ASSET_SERIAL_NUMBER+FAULT_ECU_ID+SPN_CODE+FMI_CODE+CID_CODE+EID_CODE+OCCURRENCE_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "distinct_serials|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_min|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_max|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_SERIAL_NUMBER IS NULL OR TRIM(ASSET_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(STANDARD_MANUFACTURER_CODE IS NULL OR TRIM(STANDARD_MANUFACTURER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|STANDARD_MANUFACTURER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_MODEL_AND_MODIFIER_NUMBER IS NULL OR TRIM(SALES_MODEL_AND_MODIFIER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_MODEL_AND_MODIFIER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY_DESCRIPTION IS NULL OR TRIM(PRODUCT_FAMILY_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_ALTERNATE_NAME IS NULL OR TRIM(ASSET_ALTERNATE_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_ALTERNATE_NAME",
