    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))) / NULLIF(COUNT_IF(NULLIF(TRIM(RECEIVED_DATETIME), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))), '(null)') AS "to_timestamp_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))), '(null)') AS "to_timestamp_max|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SEVERITY IS NULL OR TRIM(SEVERITY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SEVERITY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FAULT_ECU_ID IS NULL OR TRIM(FAULT_ECU_ID) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FAULT_ECU_ID",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FAULT_ECU_DESCRIPTION IS NULL OR TRIM(FAULT_ECU_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FAULT_ECU_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SPN_CODE IS NULL OR TRIM(SPN_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SPN_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(EID_CODE IS NULL OR TRIM(EID_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|EID_CODE",
