    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FAULT_TYPE_DESCRIPTION IS NULL OR TRIM(FAULT_TYPE_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|FAULT_TYPE_DESCRIPTION",
