    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_DOUBLE(TRIM(LATITUDE)))) / NULLIF(COUNT_IF(NULLIF(TRIM(LATITUDE), '') IS NOT NULL), 0), 2)), '(null)') AS "to_number_ok_pct|LATITUDE",
