    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(CREATE_TIMESTAMP)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|CREATE_TIMESTAMP"
