-- Q04  DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY
SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(ASSET_SERIAL_NUMBER, STANDARD_MANUFACTURER_CODE, RECEIVED_DATETIME))), '(null)') AS "distinct_key|ASSET_SERIAL_NUMBER+STANDARD_MANUFACTURER_CODE+RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(ASSET_SERIAL_NUMBER, STANDARD_MANUFACTURER_CODE, RECEIVED_DATETIME))), '(null)') AS "duplicate_key_rows|ASSET_SERIAL_NUMBER+STANDARD_MANUFACTURER_CODE+RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "distinct_serials|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_min|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(ASSET_SERIAL_NUMBER)))), '(null)') AS "serial_len_max|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_GUID_IDENTIFIER IS NULL OR TRIM(ASSET_GUID_IDENTIFIER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_GUID_IDENTIFIER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(STANDARD_MANUFACTURER_CODE IS NULL OR TRIM(STANDARD_MANUFACTURER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|STANDARD_MANUFACTURER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_MODEL_AND_MODIFIER_NUMBER IS NULL OR TRIM(SALES_MODEL_AND_MODIFIER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_MODEL_AND_MODIFIER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_SERIAL_NUMBER IS NULL OR TRIM(ASSET_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ASSET_ALTERNATE_NAME IS NULL OR TRIM(ASSET_ALTERNATE_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ASSET_ALTERNATE_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(EQUIPMENT_OWNER IS NULL OR TRIM(EQUIPMENT_OWNER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|EQUIPMENT_OWNER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEVICE_SERIAL_NUMBER IS NULL OR TRIM(DEVICE_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEVICE_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RECEIVED_DATETIME IS NULL OR TRIM(RECEIVED_DATETIME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(RECEIVED_DATETIME), ''))), '(null)') AS "raw_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(RECEIVED_DATETIME), ''))), '(null)') AS "raw_max|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(RECEIVED_DATETIME), '')))), '(null)') AS "raw_len_min|RECEIVED_DATETIME",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(RECEIVED_DATETIME), '')))), '(null)') AS "raw_len_max|RECEIVED_DATETIME",
