    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_DOUBLE(TRIM(IDLE_SERVICE_METER_HOURS_VALUE)))) / NULLIF(COUNT_IF(NULLIF(TRIM(IDLE_SERVICE_METER_HOURS_VALUE), '') IS NOT NULL), 0), 2)), '(null)') AS "to_number_ok_pct|IDLE_SERVICE_METER_HOURS_VALUE",
