    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(IDLE_SERVICE_METER_DATETIME)))), '(null)') AS "to_timestamp_min|IDLE_SERVICE_METER_DATETIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(IDLE_SERVICE_METER_DATETIME)))), '(null)') AS "to_timestamp_max|IDLE_SERVICE_METER_DATETIME",
