-- Q05  OLGA.COMPANY_CONFIG_TABLE
SELECT 'OLGA.COMPANY_CONFIG_TABLE' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(DEALER_CODE))), '(null)') AS "distinct_key|DEALER_CODE",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(DEALER_CODE))), '(null)') AS "duplicate_key_rows|DEALER_CODE",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE IS NULL OR TRIM(DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE_DESC IS NULL OR TRIM(DEALER_CODE_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(GENERATION_TIME IS NULL OR TRIM(GENERATION_TIME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(GENERATION_TIME), ''))), '(null)') AS "raw_min|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(GENERATION_TIME), ''))), '(null)') AS "raw_max|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(GENERATION_TIME), '')))), '(null)') AS "raw_len_min|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(GENERATION_TIME), '')))), '(null)') AS "raw_len_max|GENERATION_TIME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(GENERATION_TIME)))) / NULLIF(COUNT_IF(NULLIF(TRIM(GENERATION_TIME), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(GENERATION_TIME)))), '(null)') AS "to_timestamp_min|GENERATION_TIME",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(GENERATION_TIME)))), '(null)') AS "to_timestamp_max|GENERATION_TIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(GENERATION_TIME)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|GENERATION_TIME",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(GENERATION_TIME)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|GENERATION_TIME"
  FROM SERVICE_INTELLIGENCE.OLGA.COMPANY_CONFIG_TABLE
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|DEALER_CODE", "duplicate_key_rows|DEALER_CODE", "distinct_full_rows|*", "duplicate_full_rows|*", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|DEALER_CODE_DESC", "null_or_blank_pct|GENERATION_TIME", "raw_min|GENERATION_TIME", "raw_max|GENERATION_TIME", "raw_len_min|GENERATION_TIME", "raw_len_max|GENERATION_TIME", "to_timestamp_ok_pct|GENERATION_TIME", "to_timestamp_min|GENERATION_TIME", "to_timestamp_max|GENERATION_TIME", "to_timestamp_future_rows|GENERATION_TIME", "to_timestamp_before_2000_rows|GENERATION_TIME"));

