    COALESCE(TO_VARCHAR(MAX(STRUCTURAL_BOOST)), '(null)') AS "max|STRUCTURAL_BOOST",
    COALESCE(TO_VARCHAR(COUNT_IF(STRUCTURAL_BOOST < 0)), '(null)') AS "negative_rows|STRUCTURAL_BOOST",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(UNKNOWN_BOOST IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|UNKNOWN_BOOST",
    COALESCE(TO_VARCHAR(MIN(UNKNOWN_BOOST)), '(null)') AS "min|UNKNOWN_BOOST",
    COALESCE(TO_VARCHAR(MAX(UNKNOWN_BOOST)), '(null)') AS "max|UNKNOWN_BOOST",
