    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(UNDERCARRIAGE_OPPORTUNITY IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|UNDERCARRIAGE_OPPORTUNITY",
