    COALESCE(TO_VARCHAR(COUNT_IF(STRUCTURAL_OPPORTUNITY < 0)), '(null)') AS "negative_rows|STRUCTURAL_OPPORTUNITY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(UNKNOWN_OPPORTUNITY IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|UNKNOWN_OPPORTUNITY",
    COALESCE(TO_VARCHAR(MIN(UNKNOWN_OPPORTUNITY)), '(null)') AS "min|UNKNOWN_OPPORTUNITY",
    COALESCE(TO_VARCHAR(MAX(UNKNOWN_OPPORTUNITY)), '(null)') AS "max|UNKNOWN_OPPORTUNITY",
    COALESCE(TO_VARCHAR(COUNT_IF(UNKNOWN_OPPORTUNITY < 0)), '(null)') AS "negative_rows|UNKNOWN_OPPORTUNITY"
  FROM SERVICE_INTELLIGENCE.OLGA.CUSTOMER_TOTALS_TABLE
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|DEALER_CODE+CUSTOMER_NUMBER+DIVISION_CODE+INDUSTRY_VERTICAL_CODE+END_OF_MONTH", "duplicate_key_rows|DEALER_CODE+CUSTOMER_NUMBER+DIVISION_CODE+INDUSTRY_VERTICAL_CODE+END_OF_MONTH", "distinct_full_rows|*", "duplicate_full_rows|*", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|CUSTOMER_NUMBER", "null_or_blank_pct|DIVISION_CODE", "null_or_blank_pct|INDUSTRY_VERTICAL_CODE", "null_or_blank_pct|END_OF_MONTH", "raw_min|END_OF_MONTH", "raw_max|END_OF_MONTH", "raw_len_min|END_OF_MONTH", "raw_len_max|END_OF_MONTH", "to_timestamp_ok_pct|END_OF_MONTH", "to_timestamp_min|END_OF_MONTH", "to_timestamp_max|END_OF_MONTH", "to_timestamp_future_rows|END_OF_MONTH", "to_timestamp_before_2000_rows|END_OF_MONTH", "null_or_blank_pct|GENERATION_TIME", "raw_min|GENERATION_TIME", "raw_max|GENERATION_TIME", "raw_len_min|GENERATION_TIME", "raw_len_max|GENERATION_TIME", "to_timestamp_ok_pct|GENERATION_TIME", "to_timestamp_min|GENERATION_TIME", "to_timestamp_max|GENERATION_TIME", "to_timestamp_future_rows|GENERATION_TIME", "to_timestamp_before_2000_rows|GENERATION_TIME", "null_pct|UNDERCARRIAGE_BASE", "min|UNDERCARRIAGE_BASE", "max|UNDERCARRIAGE_BASE", "negative_rows|UNDERCARRIAGE_BASE", "null_pct|ENGINE_BASE", "min|ENGINE_BASE", "max|ENGINE_BASE", "negative_rows|ENGINE_BASE", "null_pct|GET_BASE", "min|GET_BASE", "max|GET_BASE", "negative_rows|GET_BASE", "null_pct|DRIVETRAIN_BASE", "min|DRIVETRAIN_BASE", "max|DRIVETRAIN_BASE", "negative_rows|DRIVETRAIN_BASE", "null_pct|HYDRAULICS_BASE", "min|HYDRAULICS_BASE", "max|HYDRAULICS_BASE", "negative_rows|HYDRAULICS_BASE", "null_pct|FLUIDSFILTERS_BASE", "min|FLUIDSFILTERS_BASE", "max|FLUIDSFILTERS_BASE", "negative_rows|FLUIDSFILTERS_BASE", "null_pct|MAINTENANCE_BASE", "min|MAINTENANCE_BASE", "max|MAINTENANCE_BASE", "negative_rows|MAINTENANCE_BASE", "null_pct|STRUCTURAL_BASE", "min|STRUCTURAL_BASE", "max|STRUCTURAL_BASE", "negative_rows|STRUCTURAL_BASE", "null_pct|UNKNOWN_BASE", "min|UNKNOWN_BASE