|STRUCTURAL_BOOST", "min|STRUCTURAL_BOOST", "max|STRUCTURAL_BOOST", "negative_rows|STRUCTURAL_BOOST", "null_pct|UNKNOWN_BOOST", "min|UNKNOWN_BOOST", "max|UNKNOWN_BOOST", "negative_rows|UNKNOWN_BOOST", "null_pct|UNDERCARRIAGE_OPPORTUNITY", "min|UNDERCARRIAGE_OPPORTUNITY", "max|UNDERCARRIAGE_OPPORTUNITY", "negative_rows|UNDERCARRIAGE_OPPORTUNITY", "null_pct|ENGINE_OPPORTUNITY", "min|ENGINE_OPPORTUNITY", "max|ENGINE_OPPORTUNITY", "negative_rows|ENGINE_OPPORTUNITY", "null_pct|GET_OPPORTUNITY", "min|GET_OPPORTUNITY", "max|GET_OPPORTUNITY", "negative_rows|GET_OPPORTUNITY", "null_pct|DRIVETRAIN_OPPORTUNITY", "min|DRIVETRAIN_OPPORTUNITY", "max|DRIVETRAIN_OPPORTUNITY", "negative_rows|DRIVETRAIN_OPPORTUNITY", "null_pct|HYDRAULICS_OPPORTUNITY", "min|HYDRAULICS_OPPORTUNITY", "max|HYDRAULICS_OPPORTUNITY", "negative_rows|HYDRAULICS_OPPORTUNITY", "null_pct|FLUIDSFILTERS_OPPORTUNITY", "min|FLUIDSFILTERS_OPPORTUNITY", "max|FLUIDSFILTERS_OPPORTUNITY", "negative_rows|FLUIDSFILTERS_OPPORTUNITY", "null_pct|MAINTENANCE_OPPORTUNITY", "min|MAINTENANCE_OPPORTUNITY", "max|MAINTENANCE_OPPORTUNITY", "negative_rows|MAINTENANCE_OPPORTUNITY", "null_pct|STRUCTURAL_OPPORTUNITY", "min|STRUCTURAL_OPPORTUNITY", "max|STRUCTURAL_OPPORTUNITY", "negative_rows|STRUCTURAL_OPPORTUNITY", "null_pct|UNKNOWN_OPPORTUNITY", "min|UNKNOWN_OPPORTUNITY", "max|UNKNOWN_OPPORTUNITY", "negative_rows|UNKNOWN_OPPORTUNITY"));

-- Q07  OLGA.EQUIPMENT_REPORT_DETAIL_TABLE
SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(DEALER_CODE, MANUFACTURER_CODE, SERIAL_NUMBER))), '(null)') AS "distinct_key|DEALER_CODE+MANUFACTURER_CODE+SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(DEALER_CODE, MANUFACTURER_CODE, SERIAL_NUMBER))), '(null)') AS "duplicate_key_rows|DEALER_CODE+MANUFACTURER_CODE+SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(SERIAL_NUMBER)))), '(null)') AS "distinct_serials|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_min|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_max|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER IS NULL OR TRIM(SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER_PREFIX IS NULL OR TRIM(SERIAL_NUMBER_PREFIX) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER_PREFIX",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MANUFACTURER_CODE IS NULL OR TRIM(MANUFACTURER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MANUFACTURER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_GROUP_DESC IS NULL OR TRIM(PRODUCT_GROUP_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_GROUP_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_GROUP_CODE IS NULL OR TRIM(PRODUCT_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY_DESC IS NULL OR TRIM(PRODUCT_FAMILY_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY_CODE IS NULL OR TRIM(PRODUCT_FAMILY_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MODEL IS NULL OR TRIM(MODEL) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MODEL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ENGINE_ARRANGEMENT IS NULL OR TRIM(ENGINE_ARRANGEMENT) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ENGINE_ARRANGEMENT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NAME IS NULL OR TRIM(CUSTOMER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NUMBER IS NULL OR TRIM(CUSTOMER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PARENT_CUSTOMER_NUMBER IS NULL OR TRIM(PARENT_CUSTOMER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PARENT_CUSTOMER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PARENT_CUSTOMER_NAME IS NULL OR TRIM(PARENT_CUSTOMER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PARENT_CUSTOMER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DIVISION_CODE IS NULL OR TRIM(DIVISION_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DIVISION_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DIVISION_DESC IS NULL OR TRIM(DIVISION_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DIVISION_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_CODE IS NULL OR TRIM(INDUSTRY_VERTICAL_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_DESC IS NULL OR TRIM(INDUSTRY_VERTICAL_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY IS NULL OR TRIM(INDUSTRY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NUMBER IS NULL OR TRIM(SALES_REP_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NAME IS NULL OR TRIM(SALES_REP_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_TYPE IS NULL OR TRIM(SALES_REP_TYPE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_TYPE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_SUPPORT_SEGMENTATION IS NULL OR TRIM(PRODUCT_SUPPORT_SEGMENTATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_SUPPORT_SEGMENTATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL1 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL1) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL1",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL2 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL2) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL2",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPLE_WORK_CODE IS NULL OR TRIM(PRINCIPLE_WORK_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPLE_WORK_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPLE_WORK_CODE_DESC IS NULL OR TRIM(PRINCIPLE_WORK_CODE_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPLE_WORK_CODE_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APPLICATION_CODE IS NULL OR TRIM(APPLICATION_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APPLICATION_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APPLICATION_CODE_DESC IS NULL OR TRIM(APPLICATION_CODE_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APPLICATION_CODE_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TERRITORY_INDICATOR IS NULL OR TRIM(TERRITORY_INDICATOR) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|TERRITORY_INDICATOR",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TERRITORY_INDICATOR_DESC IS NULL OR TRIM(TERRITORY_INDICATOR_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|TERRITORY_INDICATOR_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(GPS_IN_TERRITORY IS NULL OR TRIM(GPS_IN_TERRITORY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|GPS_IN_TERRITORY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CURRENT_EQUIPMENT IS NULL OR TRIM(CURRENT_EQUIPMENT) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CURRENT_EQUIPMENT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INCLUDED_EXCLUDED IS NULL OR TRIM(INCLUDED_EXCLUDED) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INCLUDED_EXCLUDED",
