to_timestamp_ok_pct|PARKED_SMU_DATE", "to_timestamp_min|PARKED_SMU_DATE", "to_timestamp_max|PARKED_SMU_DATE", "to_timestamp_future_rows|PARKED_SMU_DATE", "to_timestamp_before_2000_rows|PARKED_SMU_DATE", "null_or_blank_pct|PARKING_DEALER_REGION", "null_pct|MONTHLY_UTILIZATION", "min|MONTHLY_UTILIZATION", "max|MONTHLY_UTILIZATION", "negative_rows|MONTHLY_UTILIZATION", "null_or_blank_pct|SMU_TYPE", "null_or_blank_pct|UTILIZATION_TYPE", "null_or_blank_pct|CONNECTED_ASSET", "null_pct|SMU", "min|SMU", "max|SMU", "negative_rows|SMU", "null_pct|LAST_REPORTED_SMU", "min|LAST_REPORTED_SMU", "max|LAST_REPORTED_SMU", "negative_rows|LAST_REPORTED_SMU", "null_or_blank_pct|LAST_REPORTED_SMU_DATE", "raw_min|LAST_REPORTED_SMU_DATE", "raw_max|LAST_REPORTED_SMU_DATE", "raw_len_min|LAST_REPORTED_SMU_DATE", "raw_len_max|LAST_REPORTED_SMU_DATE", "to_timestamp_ok_pct|LAST_REPORTED_SMU_DATE", "to_timestamp_min|LAST_REPORTED_SMU_DATE", "to_timestamp_max|LAST_REPORTED_SMU_DATE", "to_timestamp_future_rows|LAST_REPORTED_SMU_DATE", "to_timestamp_before_2000_rows|LAST_REPORTED_SMU_DATE", "null_or_blank_pct|IN_SERVICE_DATE", "raw_min|IN_SERVICE_DATE", "raw_max|IN_SERVICE_DATE", "raw_len_min|IN_SERVICE_DATE", "raw_len_max|IN_SERVICE_DATE", "to_timestamp_ok_pct|IN_SERVICE_DATE", "to_timestamp_min|IN_SERVICE_DATE", "to_timestamp_max|IN_SERVICE_DATE", "to_timestamp_future_rows|IN_SERVICE_DATE", "to_timestamp_before_2000_rows|IN_SERVICE_DATE", "null_pct|LAST_INVOICE_DATE", "min|LAST_INVOICE_DATE", "max|LAST_INVOICE_DATE", "hours_since_max|LAST_INVOICE_DATE", "null_or_blank_pct|CONTRACT", "null_or_blank_pct|DUPLICATE_SERIAL_NUMBER", "null_or_blank_pct|GPS_LOCATION_REGION", "null_or_blank_pct|DUPLICATE_DEALER_REGION", "null_or_blank_pct|CALCULATION_ERROR_MESSAGE", "null_pct|PART_SALES_PREVIOUS_12_MONTHS", "min|PART_SALES_PREVIOUS_12_MONTHS", "max|PART_SALES_PREVIOUS_12_MONTHS", "negative_rows|PART_SALES_PREVIOUS_12_MONTHS", "null_pct|LABOR_SALES_PREVIOUS_12_MONTHS", "min|LABOR_SALES_PREVIOUS_12_MONTHS", "max|LABOR_SALES_PREVIOUS_12_MONTHS", "negative_rows|LABOR_SALES_PREVIOUS_12_MONTHS", "null_pct|TOTAL_SALES_PREVIOUS_12_MONTHS", "min|TOTAL_SALES_PREVIOUS_12_MONTHS", "max|TOTAL_SALES_PREVIOUS_12_MONTHS", "negative_rows|TOTAL_SALES_PREVIOUS_12_MONTHS", "null_pct|BASE_PREVIOUS_12_MONTHS", "min|BASE_PREVIOUS_12_MONTHS", "max|BASE_PREVIOUS_12_MONTHS", "negative_rows|BASE_PREVIOUS_12_MONTHS", "null_pct|BOOST_PREVIOUS_12_MONTHS", "min|BOOST_PREVIOUS_12_MONTHS", "max|BOOST_PREVIOUS_12_MONTHS", "negative_rows|BOOST_PREVIOUS_12_MONTHS", "null_pct|LABOR_OPPORTUNITY_PREVIOUS_12_MONTHS", "min|LABOR_OPPORTUNITY_PREVIOUS_12_MONTHS", "max|LABOR_OPPORTUNITY_PREVIOUS_12_MONTHS", "negative_rows|LABOR_OPPORTUNITY_PREVIOUS_12_MONTHS", "null_pct|TOTAL_OPPORTUNITY_PREVIOUS_12_MONTHS", "min|TOTAL_OPPORTUNITY_PREVIOUS_12_MONTHS", "max|TOTAL_OPPORTUNITY_PREVIOUS_12_MONTHS", "negative_rows|TOTAL_OPPORTUNITY_PREVIOUS_12_MONTHS", "null_pct|BASE_FUTURE_12_MONTHS", "min|BASE_FUTURE_12_MONTHS", "max|BASE_FUTURE_12_MONTHS", "negative_rows|BASE_FUTURE_12_MONTHS", "null_pct|LABOR_OPPORTUNITY_FUTURE_12_MONTHS", "min|LABOR_OPPORTUNITY_FUTURE_12_MONTHS", "max|LABOR_OPPORTUNITY_FUTURE_12_MONTHS", "negative_rows|LABOR_OPPORTUNITY_FUTURE_12_MONTHS", "null_pct|TOTAL_OPPORTUNITY_FUTURE_12_MONTHS", "min|TOTAL_OPPORTUNITY_FUTURE_12_MONTHS", "max|TOTAL_OPPORTUNITY_FUTURE_12_MONTHS", "negative_rows|TOTAL_OPPORTUNITY_FUTURE_12_MONTHS", "null_or_blank_pct|RELATED_SERIAL_NUMBER", "null_or_blank_pct|RELATED_MANUFACTURER_CODE", "null_or_blank_pct|RELATED_MANUFACTURER_MODEL", "null_or_blank_pct|RELATED_MANUFACTURER_NAME", "null_or_blank_pct|PRODUCT_INDUSTRY_CODE", "null_or_blank_pct|PRODUCT_INDUSTRY_DESC", "null_or_blank_pct|PRODUCT_DIVISION_CODE", "null_or_blank_pct|PRODUCT_DIVISON_DESC", "null_or_blank_pct|DEALER_CODE"));

-- Q08  OLGA.LOST_OPPORTUNITY_REPORT_TABLE
SELECT 'OLGA.LOST_OPPORTUNITY_REPORT_TABLE' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(DEALER_CODE, YEAR_MONTH, CUSTOMER_NUMBER, BRANCH_CODE, SERIAL_NUMBER, SMCS_COMPONENT_CODE, SMCS_SUB_GROUP_CODE, SMCS_GROUP_CODE, AMO_CODE, COMMERCIAL_GROUP_CODE, MAJOR_CLASS_CODE))), '(null)') AS "distinct_key|DEALER_CODE+YEAR_MONTH+CUSTOMER_NUMBER+BRANCH_CODE+SERIAL_NUMBER+SMCS_COMPONENT_CODE+SMCS_SUB_GROUP_CODE+SMCS_GROUP_CODE+AMO_CODE+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(DEALER_CODE, YEAR_MONTH, CUSTOMER_NUMBER, BRANCH_CODE, SERIAL_NUMBER, SMCS_COMPONENT_CODE, SMCS_SUB_GROUP_CODE, SMCS_GROUP_CODE, AMO_CODE, COMMERCIAL_GROUP_CODE, MAJOR_CLASS_CODE))), '(null)') AS "duplicate_key_rows|DEALER_CODE+YEAR_MONTH+CUSTOMER_NUMBER+BRANCH_CODE+SERIAL_NUMBER+SMCS_COMPONENT_CODE+SMCS_SUB_GROUP_CODE+SMCS_GROUP_CODE+AMO_CODE+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(SERIAL_NUMBER)))), '(null)') AS "distinct_serials|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_min|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_max|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE IS NULL OR TRIM(DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TERRITORY_DEALER_CODE IS NULL OR TRIM(TERRITORY_DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|TERRITORY_DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(YEAR_MONTH IS NULL OR TRIM(YEAR_MONTH) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(YEAR_MONTH), ''))), '(null)') AS "raw_min|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(YEAR_MONTH), ''))), '(null)') AS "raw_max|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(YEAR_MONTH), '')))), '(null)') AS "raw_len_min|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(YEAR_MONTH), '')))), '(null)') AS "raw_len_max|YEAR_MONTH",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH)))) / NULLIF(COUNT_IF(NULLIF(TRIM(YEAR_MONTH), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH)))), '(null)') AS "to_timestamp_min|YEAR_MONTH",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH)))), '(null)') AS "to_timestamp_max|YEAR_MONTH",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|YEAR_MONTH",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|YEAR_MONTH",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(YEAR_MONTH_DATE IS NULL OR TRIM(YEAR_MONTH_DATE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(YEAR_MONTH_DATE), ''))), '(null)') AS "raw_min|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(YEAR_MONTH_DATE), ''))), '(null)') AS "raw_max|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(YEAR_MONTH_DATE), '')))), '(null)') AS "raw_len_min|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(YEAR_MONTH_DATE), '')))), '(null)') AS "raw_len_max|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH_DATE)))) / NULLIF(COUNT_IF(NULLIF(TRIM(YEAR_MONTH_DATE), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH_DATE)))), '(null)') AS "to_timestamp_min|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH_DATE)))), '(null)') AS "to_timestamp_max|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH_DATE)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(YEAR_MONTH_DATE)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|YEAR_MONTH_DATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NUMBER IS NULL OR TRIM(CUSTOMER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CUSTOMER_NAME IS NULL OR TRIM(DEALER_CUSTOMER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CUSTOMER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_CLASSIFICATION IS NULL OR TRIM(CUSTOMER_CLASSIFICATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_CLASSIFICATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SUBCLASSIFICATION IS NULL OR TRIM(CUSTOMER_SUBCLASSIFICATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SUBCLASSIFICATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TOP_LEVEL_PARENT_NUMBER IS NULL OR TRIM(TOP_LEVEL_PARENT_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|TOP_LEVEL_PARENT_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL1 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL1) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL1",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL2 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL2) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL2",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_TYPE IS NULL OR TRIM(SALES_REP_TYPE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_TYPE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NUMBER IS NULL OR TRIM(SALES_REP_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NAME IS NULL OR TRIM(SALES_REP_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SEGMENTATION IS NULL OR TRIM(SEGMENTATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SEGMENTATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_CODE IS NULL OR TRIM(INDUSTRY_VERTICAL_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_DESCRIPTION IS NULL OR TRIM(INDUSTRY_VERTICAL_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_CODE IS NULL OR TRIM(INDUSTRY_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BRANCH_CODE IS NULL OR TRIM(BRANCH_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|BRANCH_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BRANCH_DESCRIPTION IS NULL OR TRIM(BRANCH_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|BRANCH_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DIVISION_CODE IS NULL OR TRIM(DIVISION_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DIVISION_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER IS NULL OR TRIM(SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MONTHLY_UTILIZATION_RATE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|MONTHLY_UTILIZATION_RATE",
    COALESCE(TO_VARCHAR(MIN(MONTHLY_UTILIZATION_RATE)), '(null)') AS "min|MONTHLY_UTILIZATION_RATE",
    COALESCE(TO_VARCHAR(MAX(MONTHLY_UTILIZATION_RATE)), '(null)') AS "max|MONTHLY_UTILIZATION_RATE",
    COALESCE(TO_VARCHAR(COUNT_IF(MONTHLY_UTILIZATION_RATE < 0)), '(null)') AS "negative_rows|MONTHLY_UTILIZATION_RATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CURRENT_SMU IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|CURRENT_SMU",
    COALESCE(TO_VARCHAR(MIN(CURRENT_SMU)), '(null)') AS "min|CURRENT_SMU",
    COALESCE(TO_VARCHAR(MAX(CURRENT_SMU)), '(null)') AS "max|CURRENT_SMU",
    COALESCE(TO_VARCHAR(COUNT_IF(CURRENT_SMU < 0)), '(null)') AS "negative_rows|CURRENT_SMU",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY_ABBREVIATION IS NULL OR TRIM(PRODUCT_FAMILY_ABBREVIATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY_ABBREVIATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY IS NULL OR TRIM(PRODUCT_FAMILY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_MODEL IS NULL OR TRIM(SALES_MODEL) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_MODEL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER_PREFIX IS NULL OR TRIM(SERIAL_NUMBER_PREFIX) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER_PREFIX",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPAL_WORK_CODE IS NULL OR TRIM(PRINCIPAL_WORK_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPAL_WORK_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPAL_WORK_CODE_DESCRIPTION IS NULL OR TRIM(PRINCIPAL_WORK_CODE_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPAL_WORK_CODE_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APPLICATION_CODE IS NULL OR TRIM(APPLICATION_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APPLICATION_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APPLICATION_CODE_DESCRIPTION IS NULL OR TRIM(APPLICATION_CODE_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APPLICATION_CODE_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_COMPONENT_CODE IS NULL OR TRIM(SMCS_COMPONENT_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_COMPONENT_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_COMPONENT_CODE_DESCRIPTION IS NULL OR TRIM(SMCS_COMPONENT_CODE_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_COMPONENT_CODE_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_SUB_GROUP_CODE IS NULL OR TRIM(SMCS_SUB_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_SUB_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_SUB_GROUP_DESCRIPTION IS NULL OR TRIM(SMCS_SUB_GROUP_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_SUB_GROUP_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_GROUP_CODE IS NULL OR TRIM(SMCS_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_GROUP_DESCRIPTION IS NULL OR TRIM(SMCS_GROUP_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_GROUP_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(AMO_CODE IS NULL OR TRIM(AMO_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|AMO_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(AMO_DESCRIPTION IS NULL OR TRIM(AMO_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|AMO_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMMERCIAL_GROUP_CODE IS NULL OR TRIM(COMMERCIAL_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COMMERCIAL_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMMERCIAL_GROUP_DESCRIPTION IS NULL OR TRIM(COMMERCIAL_GROUP_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COMMERCIAL_GROUP_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MAJOR_CLASS_CODE IS NULL OR TRIM(MAJOR_CLASS_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MAJOR_CLASS_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MAJOR_CLASS_DESCRIPTION IS NULL OR TRIM(MAJOR_CLASS_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MAJOR_CLASS_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_SCP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|SALES_SCP",
    COALESCE(TO_VARCHAR(MIN(SALES_SCP)), '(null)') AS "min|SALES_SCP",
    COALESCE(TO_VARCHAR(MAX(SALES_SCP)), '(null)') AS "max|SALES_SCP",
    COALESCE(TO_VARCHAR(COUNT_IF(SALES_SCP < 0)), '(null)') AS "negative_rows|SALES_SCP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BASE_SCP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|BASE_SCP",
    COALESCE(TO_VARCHAR(MIN(BASE_SCP)), '(null)') AS "min|BASE_SCP",
    COALESCE(TO_VARCHAR(MAX(BASE_SCP)), '(null)') AS "max|BASE_SCP",
    COALESCE(TO_VARCHAR(COUNT_IF(BASE_SCP < 0)), '(null)') AS "negative_rows|BASE_SCP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BOOST_SCP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|BOOST_SCP",
    COALESCE(TO_VARCHAR(MIN(BOOST_SCP)), '(null)') AS "min|BOOST_SCP",
    COALESCE(TO_VARCHAR(MAX(BOOST_SCP)), '(null)') AS "max|BOOST_SCP",
    COALESCE(TO_VARCHAR(COUNT_IF(BOOST_SCP < 0)), '(null)') AS "negative_rows|BOOST_SCP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OPPORTUNITY_SCP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(MIN(OPPORTUNITY_SCP)), '(null)') AS "min|OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(MAX(OPPORTUNITY_SCP)), '(null)') AS "max|OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(COUNT_IF(OPPORTUNITY_SCP < 0)), '(null)') AS "negative_rows|OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LOST_OPPORTUNITY_SCP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LOST_OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(MIN(LOST_OPPORTUNITY_SCP)), '(null)') AS "min|LOST_OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(MAX(LOST_OPPORTUNITY_SCP)), '(null)') AS "max|LOST_OPPORTUNITY_SCP",
    COALESCE(TO_VARCHAR(COUNT_IF(LOST_OPPORTUNITY_SCP < 0)), '(null)') AS "negative_rows|LOST_OPPORTUNITY_SCP"
  FROM SERVICE_INTELLIGENCE.OLGA.LOST_OPPORTUNITY_REPORT_TABLE
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|DEALER_CODE+YEAR_MONTH+CUSTOMER_NUMBER+BRANCH_CODE+SERIAL_NUMBER+SMCS_COMPONENT_CODE+SMCS_SUB_GROUP_CODE+SMCS_GROUP_CODE+AMO_CODE+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE", "duplicate_key_rows|DEALER_CODE+YEAR_MONTH+CUSTOMER_NUMBER+BRANCH_CODE+SERIAL_NUMBER+SMCS_COMPONENT_CODE+SMCS_SUB_GROUP_CODE+SMCS_GROUP_CODE+AMO_CODE+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE", "distinct_full_rows|*", "duplicate_full_rows|*", "distinct_serials|SERIAL_NUMBER", "serial_len_min|SERIAL_NUMBER", "serial_len_max|SERIAL_NUMBER", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|TERRITORY_DEALER_CODE", "null_or_blank_pct|YEAR_MONTH", "raw_min|YEAR_MONTH", "raw_max|YEAR_MONTH", "raw_len_min|YEAR_MONTH", "raw_len_max|YEAR_MONTH", "to_timestamp_ok_pct|YEAR_MONTH", "to_timestamp_min|YEAR_MONTH", "to_timestamp_max|YEAR_MONTH", "to_timestamp_future_rows|YEAR_MONTH", "to_timestamp_before_2000_rows|YEAR_MONTH", "null_or_blank_pct|YEAR_MONTH_DATE", "raw_min|YEAR_MONTH_DATE", "raw_max|YEAR_MONTH_DATE", "raw_len_min|YEAR_MONTH_DATE", "raw_len_max|YEAR_MONTH_DATE", "to_timestamp_ok_pct|YEAR_MONTH_DATE", "to_timestamp_min|YEAR_MONTH_DATE", "to_timestamp_max|YEAR_MONTH_DATE", "to_timestamp_future_rows|YEAR_MONTH_DATE", "to_timestamp_before_2000_rows|YEAR_MONTH_DATE", "null_or_blank_pct|CUSTOMER_NUMBER", "null_or_blank_pct|DEALER_CUSTOMER_NAME", "null_or_blank_pct|CUSTOMER_CLASSIFICATION", "null_or_blank_pct|CUSTOMER_SUBCLASSIFICATION", "null_or_blank_pct|TOP_LEVEL_PARENT_NUMBER", "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL1", "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL2", "null_or_blank_pct|SALES_REP_TYPE", "null_or_blank_pct|SALES_REP_NUMBER", "null_or_blank_pct|SALES_REP_NAME", "null_or_blank_pct|SEGMENTATION", "null_or_blank_pct|INDUSTRY_VERTICAL_CODE", "null_or_blank_pct|INDUSTRY_VERTICAL_DESCRIPTION", "null_or_blank_pct|INDUSTRY_CODE", "null_or_blank_pct|BRANCH_CODE", "null_or_blank_pct|BRANCH_DESCRIPTION", "null_or_blank_pct|DIVISION_CODE", "null_or_blank_pct|SERIAL_NUMBER", "null_pct|MONTHLY_UTILIZATION_RATE", "min|MONTHLY_UTILIZATION_RATE", "max|MONTHLY_UTILIZATION_RATE", "negative_rows|MONTHLY_UTILIZATION_RATE", "null_pct|CURRENT_SMU", "min|CURRENT_SMU", "max|CURRENT_SMU", "negative_rows|CURRENT_SMU", "null_or_blank_pct|PRODUCT_FAMILY_ABBREVIATION", "null_or_blank_pct|PRODUCT_FAMILY", "null_or_blank_pct|SALES_MODEL", "null_or_blank_pct|SERIAL_NUMBER_PREFIX", "null_or_blank_pct|PRINCIPAL_WORK_CODE", "null_or_blank_pct|PRINCIPAL_WORK_CODE_DESCRIPTION", "null_or_blank_pct|APPLICATION_CODE", "null_or_blank_pct|APPLICATION_CODE_DESCRIPTION", "null_or_blank_pct|SMCS_COMPONENT_CODE", "null_or_blank_pct|SMCS_COMPONENT_CODE_DESCRIPTION", "null_or_blank_pct|SMCS_SUB_GROUP_CODE", "null_or_blank_pct|SMCS_SUB_GROUP_DESCRIPTION", "null_or_blank_pct|SMCS_GROUP_CODE", "null_or_blank_pct|SMCS_GROUP_DESCRIPTION", "null_or_blank_pct|AMO_CODE", "null_or_blank_pct|AMO_DESCRIPTION", "null_or_blank_pct|COMMERCIAL_GROUP_CODE", "null_or_blank_pct|COMMERCIAL_GROUP_DESCRIPTION", "null_or_blank_pct|MAJOR_CLASS_CODE", "null_or_blank_pct|MAJOR_CLASS_DESCRIPTION", "null_pct|SALES_SCP", "min|SALES_SCP", "max|SALES_SCP", "negative_rows|SALES_SCP", "null_pct|BASE_SCP", "min|BASE_SCP", "max|BASE_SCP", "negative_rows|BASE_SCP", "null_pct|BOOST_SCP", "min|BOOST_SCP", "max|BOOST_SCP", "negative_rows|BOOST_SCP", "null_pct|OPPORTUNITY_SCP", "min|OPPORTUNITY_SCP", "max|OPPORTUNITY_SCP", "negative_rows|OPPORTUNITY_SCP", "null_pct|LOST_OPPORTUNITY_SCP", "min|LOST_OPPORTUNITY_SCP", "max|LOST_OPPORTUNITY_SCP", "negative_rows|LOST_OPPORTUNITY_SCP"));

-- Q09  OLGA.OPPORTUNITIES_TABLE
SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(OPPORTUNITY_KEY))), '(null)') AS "distinct_key|OPPORTUNITY_KEY",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(OPPORTUNITY_KEY))), '(null)') AS "duplicate_key_rows|OPPORTUNITY_KEY",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT UPPER(TRIM(SERIAL_NUMBER)))), '(null)') AS "distinct_serials|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MIN(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_min|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(MAX(LENGTH(TRIM(SERIAL_NUMBER)))), '(null)') AS "serial_len_max|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NAME IS NULL OR TRIM(CUSTOMER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_NUMBER IS NULL OR TRIM(CUSTOMER_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_SUPPORT_SEGMENTATION IS NULL OR TRIM(PRODUCT_SUPPORT_SEGMENTATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_SUPPORT_SEGMENTATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER_PREFIX IS NULL OR TRIM(SERIAL_NUMBER_PREFIX) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER_PREFIX",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SERIAL_NUMBER IS NULL OR TRIM(SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MODEL IS NULL OR TRIM(MODEL) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MODEL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(ENGINE_ARRANGEMENT IS NULL OR TRIM(ENGINE_ARRANGEMENT) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|ENGINE_ARRANGEMENT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_CODE IS NULL OR TRIM(INDUSTRY_VERTICAL_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(INDUSTRY_VERTICAL_DESC IS NULL OR TRIM(INDUSTRY_VERTICAL_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|INDUSTRY_VERTICAL_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CIC_CODE IS NULL OR TRIM(CIC_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CIC_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NUMBER IS NULL OR TRIM(SALES_REP_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_NAME IS NULL OR TRIM(SALES_REP_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SALES_REP_TYPE IS NULL OR TRIM(SALES_REP_TYPE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SALES_REP_TYPE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_CLASSIFICATION IS NULL OR TRIM(CUSTOMER_CLASSIFICATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_CLASSIFICATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SUB_CLASSIFICATION IS NULL OR TRIM(CUSTOMER_SUB_CLASSIFICATION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SUB_CLASSIFICATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL1 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL1) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL1",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CUSTOMER_SEGMENT_LEVEL2 IS NULL OR TRIM(CUSTOMER_SEGMENT_LEVEL2) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL2",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRODUCT_FAMILY IS NULL OR TRIM(PRODUCT_FAMILY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRODUCT_FAMILY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPLE_WORK_CODE IS NULL OR TRIM(PRINCIPLE_WORK_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPLE_WORK_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PRINCIPLE_WORK_DESCRIPTION IS NULL OR TRIM(PRINCIPLE_WORK_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PRINCIPLE_WORK_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APP_CODE IS NULL OR TRIM(APP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(APP_CODE_DESCRIPTION IS NULL OR TRIM(APP_CODE_DESCRIPTION) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|APP_CODE_DESCRIPTION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMU IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|SMU",
    COALESCE(TO_VARCHAR(MIN(SMU)), '(null)') AS "min|SMU",
    COALESCE(TO_VARCHAR(MAX(SMU)), '(null)') AS "max|SMU",
    COALESCE(TO_VARCHAR(COUNT_IF(SMU < 0)), '(null)') AS "negative_rows|SMU",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MONTHLY_UTILIZATION IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|MONTHLY_UTILIZATION",
    COALESCE(TO_VARCHAR(MIN(MONTHLY_UTILIZATION)), '(null)') AS "min|MONTHLY_UTILIZATION",
    COALESCE(TO_VARCHAR(MAX(MONTHLY_UTILIZATION)), '(null)') AS "max|MONTHLY_UTILIZATION",
    COALESCE(TO_VARCHAR(COUNT_IF(MONTHLY_UTILIZATION < 0)), '(null)') AS "negative_rows|MONTHLY_UTILIZATION",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(UTILIZATION_TYPE IS NULL OR TRIM(UTILIZATION_TYPE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|UTILIZATION_TYPE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CONNECTED_ASSET IS NULL OR TRIM(CONNECTED_ASSET) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CONNECTED_ASSET",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LAST_REPORTED_SMU IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LAST_REPORTED_SMU",
    COALESCE(TO_VARCHAR(MIN(LAST_REPORTED_SMU)), '(null)') AS "min|LAST_REPORTED_SMU",
    COALESCE(TO_VARCHAR(MAX(LAST_REPORTED_SMU)), '(null)') AS "max|LAST_REPORTED_SMU",
    COALESCE(TO_VARCHAR(COUNT_IF(LAST_REPORTED_SMU < 0)), '(null)') AS "negative_rows|LAST_REPORTED_SMU",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LAST_REPORTED_SMU_DATE IS NULL OR TRIM(LAST_REPORTED_SMU_DATE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(LAST_REPORTED_SMU_DATE), ''))), '(null)') AS "raw_min|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(LAST_REPORTED_SMU_DATE), ''))), '(null)') AS "raw_max|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(LAST_REPORTED_SMU_DATE), '')))), '(null)') AS "raw_len_min|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(LAST_REPORTED_SMU_DATE), '')))), '(null)') AS "raw_len_max|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(LAST_REPORTED_SMU_DATE)))) / NULLIF(COUNT_IF(NULLIF(TRIM(LAST_REPORTED_SMU_DATE), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(LAST_REPORTED_SMU_DATE)))), '(null)') AS "to_timestamp_min|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(LAST_REPORTED_SMU_DATE)))), '(null)') AS "to_timestamp_max|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(LAST_REPORTED_SMU_DATE)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(LAST_REPORTED_SMU_DATE)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|LAST_REPORTED_SMU_DATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OPPORTUNITY_SOURCE IS NULL OR TRIM(OPPORTUNITY_SOURCE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OPPORTUNITY_SOURCE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_GROUP_CODE IS NULL OR TRIM(SMCS_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_GROUP_DESC IS NULL OR TRIM(SMCS_GROUP_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_GROUP_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_SUBGROUP_CODE IS NULL OR TRIM(SMCS_SUBGROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_SUBGROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(SMCS_SUBGROUP_DESC IS NULL OR TRIM(SMCS_SUBGROUP_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|SMCS_SUBGROUP_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMPONENT_CODE IS NULL OR TRIM(COMPONENT_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COMPONENT_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMPONENT_DESC IS NULL OR TRIM(COMPONENT_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COMPONENT_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(JOB_CODE IS NULL OR TRIM(JOB_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|JOB_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(JOB_DESC IS NULL OR TRIM(JOB_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|JOB_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MODIFIER_CODE IS NULL OR TRIM(MODIFIER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MODIFIER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MODIFIER_DESC IS NULL OR TRIM(MODIFIER_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MODIFIER_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(WORK_APP_CODE IS NULL OR TRIM(WORK_APP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|WORK_APP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(WORK_APP_DESC IS NULL OR TRIM(WORK_APP_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|WORK_APP_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMP_QTY IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|COMP_QTY",
    COALESCE(TO_VARCHAR(MIN(COMP_QTY)), '(null)') AS "min|COMP_QTY",
    COALESCE(TO_VARCHAR(MAX(COMP_QTY)), '(null)') AS "max|COMP_QTY",
    COALESCE(TO_VARCHAR(COUNT_IF(COMP_QTY < 0)), '(null)') AS "negative_rows|COMP_QTY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TARGET_SMU IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|TARGET_SMU",
    COALESCE(TO_VARCHAR(MIN(TARGET_SMU)), '(null)') AS "min|TARGET_SMU",
    COALESCE(TO_VARCHAR(MAX(TARGET_SMU)), '(null)') AS "max|TARGET_SMU",
    COALESCE(TO_VARCHAR(COUNT_IF(TARGET_SMU < 0)), '(null)') AS "negative_rows|TARGET_SMU",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TARGET_DATE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|TARGET_DATE",
    COALESCE(TO_VARCHAR(MIN(TARGET_DATE)), '(null)') AS "min|TARGET_DATE",
    COALESCE(TO_VARCHAR(MAX(TARGET_DATE)), '(null)') AS "max|TARGET_DATE",
    COALESCE(TO_VARCHAR(DATEDIFF('hour', MAX(TARGET_DATE), CURRENT_TIMESTAMP())), '(null)') AS "hours_since_max|TARGET_DATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(FIRST_INTERVAL IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|FIRST_INTERVAL",
    COALESCE(TO_VARCHAR(MIN(FIRST_INTERVAL)), '(null)') AS "min|FIRST_INTERVAL",
    COALESCE(TO_VARCHAR(MAX(FIRST_INTERVAL)), '(null)') AS "max|FIRST_INTERVAL",
    COALESCE(TO_VARCHAR(COUNT_IF(FIRST_INTERVAL < 0)), '(null)') AS "negative_rows|FIRST_INTERVAL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(NEXT_INTERVAL IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|NEXT_INTERVAL",
    COALESCE(TO_VARCHAR(MIN(NEXT_INTERVAL)), '(null)') AS "min|NEXT_INTERVAL",
    COALESCE(TO_VARCHAR(MAX(NEXT_INTERVAL)), '(null)') AS "max|NEXT_INTERVAL",
    COALESCE(TO_VARCHAR(COUNT_IF(NEXT_INTERVAL < 0)), '(null)') AS "negative_rows|NEXT_INTERVAL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LABOR_HOURS IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LABOR_HOURS",
    COALESCE(TO_VARCHAR(MIN(LABOR_HOURS)), '(null)') AS "min|LABOR_HOURS",
    COALESCE(TO_VARCHAR(MAX(LABOR_HOURS)), '(null)') AS "max|LABOR_HOURS",
    COALESCE(TO_VARCHAR(COUNT_IF(LABOR_HOURS < 0)), '(null)') AS "negative_rows|LABOR_HOURS",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LABOR_VALUE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LABOR_VALUE",
    COALESCE(TO_VARCHAR(MIN(LABOR_VALUE)), '(null)') AS "min|LABOR_VALUE",
    COALESCE(TO_VARCHAR(MAX(LABOR_VALUE)), '(null)') AS "max|LABOR_VALUE",
    COALESCE(TO_VARCHAR(COUNT_IF(LABOR_VALUE < 0)), '(null)') AS "negative_rows|LABOR_VALUE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BASE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|BASE",
    COALESCE(TO_VARCHAR(MIN(BASE)), '(null)') AS "min|BASE",
    COALESCE(TO_VARCHAR(MAX(BASE)), '(null)') AS "max|BASE",
    COALESCE(TO_VARCHAR(COUNT_IF(BASE < 0)), '(null)') AS "negative_rows|BASE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TOTAL_VALUE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|TOTAL_VALUE",
    COALESCE(TO_VARCHAR(MIN(TOTAL_VALUE)), '(null)') AS "min|TOTAL_VALUE",
    COALESCE(TO_VARCHAR(MAX(TOTAL_VALUE)), '(null)') AS "max|TOTAL_VALUE",
    COALESCE(TO_VARCHAR(COUNT_IF(TOTAL_VALUE < 0)), '(null)') AS "negative_rows|TOTAL_VALUE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LEAD_SCORE IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LEAD_SCORE",
    COALESCE(TO_VARCHAR(MIN(LEAD_SCORE)), '(null)') AS "min|LEAD_SCORE",
    COALESCE(TO_VARCHAR(MAX(LEAD_SCORE)), '(null)') AS "max|LEAD_SCORE",
    COALESCE(TO_VARCHAR(COUNT_IF(LEAD_SCORE < 0)), '(null)') AS "negative_rows|LEAD_SCORE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CONFIDENCE_INDEX IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|CONFIDENCE_INDEX",
    COALESCE(TO_VARCHAR(MIN(CONFIDENCE_INDEX)), '(null)') AS "min|CONFIDENCE_INDEX",
    COALESCE(TO_VARCHAR(MAX(CONFIDENCE_INDEX)), '(null)') AS "max|CONFIDENCE_INDEX",
    COALESCE(TO_VARCHAR(COUNT_IF(CONFIDENCE_INDEX < 0)), '(null)') AS "negative_rows|CONFIDENCE_INDEX",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(CONTRACT IS NULL OR TRIM(CONTRACT) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|CONTRACT",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(STATE IS NULL OR TRIM(STATE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|STATE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COUNTY IS NULL OR TRIM(COUNTY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COUNTY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(POSTAL_CODE IS NULL OR TRIM(POSTAL_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|POSTAL_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DIVISION_CODE IS NULL OR TRIM(DIVISION_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DIVISION_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DIVISION_DESC IS NULL OR TRIM(DIVISION_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DIVISION_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RELATED_SERIAL_NUMBER IS NULL OR TRIM(RELATED_SERIAL_NUMBER) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RELATED_SERIAL_NUMBER",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RELATED_MANUFACTURER_CODE IS NULL OR TRIM(RELATED_MANUFACTURER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RELATED_MANUFACTURER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RELATED_MANUFACTURER_MODEL IS NULL OR TRIM(RELATED_MANUFACTURER_MODEL) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RELATED_MANUFACTURER_MODEL",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(RELATED_MANUFACTURER_NAME IS NULL OR TRIM(RELATED_MANUFACTURER_NAME) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|RELATED_MANUFACTURER_NAME",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OPPORTUNITY_KEY IS NULL OR TRIM(OPPORTUNITY_KEY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OPPORTUNITY_KEY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OPPORTUNITY_ID IS NULL OR TRIM(OPPORTUNITY_ID) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OPPORTUNITY_ID",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(TERRITORY_DEALER_CODE IS NULL OR TRIM(TERRITORY_DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|TERRITORY_DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE IS NULL OR TRIM(DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BRANCH_CODE IS NULL OR TRIM(BRANCH_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|BRANCH_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(BRANCH_DESC IS NULL OR TRIM(BRANCH_DESC) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|BRANCH_DESC",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(END_OF_MONTH IS NULL OR TRIM(END_OF_MONTH) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MIN(NULLIF(TRIM(END_OF_MONTH), ''))), '(null)') AS "raw_min|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MAX(NULLIF(TRIM(END_OF_MONTH), ''))), '(null)') AS "raw_max|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MIN(LENGTH(NULLIF(TRIM(END_OF_MONTH), '')))), '(null)') AS "raw_len_min|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MAX(LENGTH(NULLIF(TRIM(END_OF_MONTH), '')))), '(null)') AS "raw_len_max|END_OF_MONTH",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT(TRY_TO_TIMESTAMP_NTZ(TRIM(END_OF_MONTH)))) / NULLIF(COUNT_IF(NULLIF(TRIM(END_OF_MONTH), '') IS NOT NULL), 0), 2)), '(null)') AS "to_timestamp_ok_pct|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MIN(TRY_TO_TIMESTAMP_NTZ(TRIM(END_OF_MONTH)))), '(null)') AS "to_timestamp_min|END_OF_MONTH",
    COALESCE(TO_VARCHAR(MAX(TRY_TO_TIMESTAMP_NTZ(TRIM(END_OF_MONTH)))), '(null)') AS "to_timestamp_max|END_OF_MONTH",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(END_OF_MONTH)) > CURRENT_TIMESTAMP()::TIMESTAMP_NTZ + INTERVAL '1 day')), '(null)') AS "to_timestamp_future_rows|END_OF_MONTH",
    COALESCE(TO_VARCHAR(COUNT_IF(TRY_TO_TIMESTAMP_NTZ(TRIM(END_OF_MONTH)) < '2000-01-01'::TIMESTAMP_NTZ)), '(null)') AS "to_timestamp_before_2000_rows|END_OF_MONTH",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LAST_UPDATE_TIMESTAMP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MIN(LAST_UPDATE_TIMESTAMP)), '(null)') AS "min|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MAX(LAST_UPDATE_TIMESTAMP)), '(null)') AS "max|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(DATEDIFF('hour', MAX(LAST_UPDATE_TIMESTAMP), CURRENT_TIMESTAMP())), '(null)') AS "hours_since_max|LAST_UPDATE_TIMESTAMP"
  FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|OPPORTUNITY_KEY", "duplicate_key_rows|OPPORTUNITY_KEY", "distinct_full_rows|*", "duplicate_full_rows|*", "distinct_serials|SERIAL_NUMBER", "serial_len_min|SERIAL_NUMBER", "serial_len_max|SERIAL_NUMBER", "null_or_blank_pct|CUSTOMER_NAME", "null_or_blank_pct|CUSTOMER_NUMBER", "null_or_blank_pct|PRODUCT_SUPPORT_SEGMENTATION", "null_or_blank_pct|SERIAL_NUMBER_PREFIX", "null_or_blank_pct|SERIAL_NUMBER", "null_or_blank_pct|MODEL", "null_or_blank_pct|ENGINE_ARRANGEMENT", "null_or_blank_pct|INDUSTRY_VERTICAL_CODE", "null_or_blank_pct|INDUSTRY_VERTICAL_DESC", "null_or_blank_pct|CIC_CODE", "null_or_blank_pct|SALES_REP_NUMBER", "null_or_blank_pct|SALES_REP_NAME", "null_or_blank_pct|SALES_REP_TYPE", "null_or_blank_pct|CUSTOMER_CLASSIFICATION", "null_or_blank_pct|CUSTOMER_SUB_CLASSIFICATION", "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL1", "null_or_blank_pct|CUSTOMER_SEGMENT_LEVEL2", "null_or_blank_pct|PRODUCT_FAMILY", "null_or_blank_pct|PRINCIPLE_WORK_CODE", "null_or_blank_pct|PRINCIPLE_WORK_DESCRIPTION", "null_or_blank_pct|APP_CODE", "null_or_blank_pct|APP_CODE_DESCRIPTION", "null_pct|SMU", "min|SMU", "max|SMU", "negative_rows|SMU", "null_pct|MONTHLY_UTILIZATION", "min|MONTHLY_UTILIZATION", "max|MONTHLY_UTILIZATION", "negative_rows|MONTHLY_UTILIZATION", "null_or_blank_pct|UTILIZATION_TYPE", "null_or_blank_pct|CONNECTED_ASSET", "null_pct|LAST_REPORTED_SMU", "min|LAST_REPORTED_SMU", "max|LAST_REPORTED_SMU", "negative_rows|LAST_REPORTED_SMU", "null_or_blank_pct|LAST_REPORTED_SMU_DATE", "raw_min|LAST_REPORTED_SMU_DATE", "raw_max|LAST_REPORTED_SMU_DATE", "raw_len_min|LAST_REPORTED_SMU_DATE", "raw_len_max|LAST_REPORTED_SMU_DATE", "to_timestamp_ok_pct|LAST_REPORTED_SMU_DATE", "to_timestamp_min|LAST_REPORTED_SMU_DATE", "to_timestamp_max|LAST_REPORTED_SMU_DATE", "to_timestamp_future_rows|LAST_REPORTED_SMU_DATE", "to_timestamp_before_2000_rows|LAST_REPORTED_SMU_DATE", "null_or_blank_pct|OPPORTUNITY_SOURCE", "null_or_blank_pct|SMCS_GROUP_CODE", "null_or_blank_pct|SMCS_GROUP_DESC", "null_or_blank_pct|SMCS_SUBGROUP_CODE", "null_or_blank_pct|SMCS_SUBGROUP_DESC", "null_or_blank_pct|COMPONENT_CODE", "null_or_blank_pct|COMPONENT_DESC", "null_or_blank_pct|JOB_CODE", "null_or_blank_pct|JOB_DESC", "null_or_blank_pct|MODIFIER_CODE", "null_or_blank_pct|MODIFIER_DESC", "null_or_blank_pct|WORK_APP_CODE", "null_or_blank_pct|WORK_APP_DESC", "null_pct|COMP_QTY", "min|COMP_QTY", "max|COMP_QTY", "negative_rows|COMP_QTY", "null_pct|TARGET_SMU", "min|TARGET_SMU", "max|TARGET_SMU", "negative_rows|TARGET_SMU", "null_pct|TARGET_DATE", "min|TARGET_DATE", "max|TARGET_DATE", "hours_since_max|TARGET_DATE", "null_pct|FIRST_INTERVAL", "min|FIRST_INTERVAL", "max|FIRST_INTERVAL", "negative_rows|FIRST_INTERVAL", "null_pct|NEXT_INTERVAL", "min|NEXT_INTERVAL", "max|NEXT_INTERVAL", "negative_rows|NEXT_INTERVAL", "null_pct|LABOR_HOURS", "min|LABOR_HOURS", "max|LABOR_HOURS", "negative_rows|LABOR_HOURS", "null_pct|LABOR_VALUE", "min|LABOR_VALUE", "max|LABOR_VALUE", "negative_rows|LABOR_VALUE", "null_pct|BASE", "min|BASE", "max|BASE", "negative_rows|BASE", "null_pct|TOTAL_VALUE", "min|TOTAL_VALUE", "max|TOTAL_VALUE", "negative_rows|TOTAL_VALUE", "null_pct|LEAD_SCORE", "min|LEAD_SCORE", "max|LEAD_SCORE", "negative_rows|LEAD_SCORE", "null_pct|CONFIDENCE_INDEX", "min|CONFIDENCE_INDEX", "max|CONFIDENCE_INDEX", "negative_rows|CONFIDENCE_INDEX", "null_or_blank_pct|CONTRACT", "null_or_blank_pct|STATE", "null_or_blank_pct|COUNTY", "null_or_blank_pct|POSTAL_CODE", "null_or_blank_pct|DIVISION_CODE", "null_or_blank_pct|DIVISION_DESC", "null_or_blank_pct|RELATED_SERIAL_NUMBER", "null_or_blank_pct|RELATED_MANUFACTURER_CODE", "null_or_blank_pct|RELATED_MANUFACTURER_MODEL", "null_or_blank_pct|RELATED_MANUFACTURER_NAME", "null_or_blank_pct|OPPORTUNITY_KEY", "null_or_blank_pct|OPPORTUNITY_ID", "null_or_blank_pct|TERRITORY_DEALER_CODE", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|BRANCH_CODE", "null_or_blank_pct|BRANCH_DESC", "null_or_blank_pct|END_OF_MONTH", "raw_min|END_OF_MONTH", "raw_max|END_OF_MONTH", "raw_len_min|END_OF_MONTH", "raw_len_max|END_OF_MONTH", "to_timestamp_ok_pct|END_OF_MONTH", "to_timestamp_min|END_OF_MONTH", "to_timestamp_max|END_OF_MONTH", "to_timestamp_future_rows|END_OF_MONTH", "to_timestamp_before_2000_rows|END_OF_MONTH", "null_pct|LAST_UPDATE_TIMESTAMP", "min|LAST_UPDATE_TIMESTAMP", "max|LAST_UPDATE_TIMESTAMP", "hours_since_max|LAST_UPDATE_TIMESTAMP"));

-- Q10  OLGA.OPPORTUNITY_MAJORCLASS_SUBCATEGORY_PARTCOST_TABLE
SELECT 'OLGA.OPPORTUNITY_MAJORCLASS_SUBCATEGORY_PARTCOST_TABLE' AS table_name,
       SPLIT_PART(metric, '|', 1) AS check_name,
       SPLIT_PART(metric, '|', 2) AS column_name,
       value
FROM (
  SELECT
    COALESCE(TO_VARCHAR(COUNT(*)), '(null)') AS "rows|*",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(OPPORTUNITY_KEY, COMMERCIAL_GROUP_CODE, MAJOR_CLASS_CODE, PARTS_PRODUCT_CODE, AMO_CODE))), '(null)') AS "distinct_key|OPPORTUNITY_KEY+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE+PARTS_PRODUCT_CODE+AMO_CODE",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(OPPORTUNITY_KEY, COMMERCIAL_GROUP_CODE, MAJOR_CLASS_CODE, PARTS_PRODUCT_CODE, AMO_CODE))), '(null)') AS "duplicate_key_rows|OPPORTUNITY_KEY+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE+PARTS_PRODUCT_CODE+AMO_CODE",
    COALESCE(TO_VARCHAR(COUNT(DISTINCT HASH(*))), '(null)') AS "distinct_full_rows|*",
    COALESCE(TO_VARCHAR(COUNT(*) - COUNT(DISTINCT HASH(*))), '(null)') AS "duplicate_full_rows|*",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(OPPORTUNITY_KEY IS NULL OR TRIM(OPPORTUNITY_KEY) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|OPPORTUNITY_KEY",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(COMMERCIAL_GROUP_CODE IS NULL OR TRIM(COMMERCIAL_GROUP_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|COMMERCIAL_GROUP_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(MAJOR_CLASS_CODE IS NULL OR TRIM(MAJOR_CLASS_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|MAJOR_CLASS_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PART_COST IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|PART_COST",
    COALESCE(TO_VARCHAR(MIN(PART_COST)), '(null)') AS "min|PART_COST",
    COALESCE(TO_VARCHAR(MAX(PART_COST)), '(null)') AS "max|PART_COST",
    COALESCE(TO_VARCHAR(COUNT_IF(PART_COST < 0)), '(null)') AS "negative_rows|PART_COST",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PART_COST_USD IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|PART_COST_USD",
    COALESCE(TO_VARCHAR(MIN(PART_COST_USD)), '(null)') AS "min|PART_COST_USD",
    COALESCE(TO_VARCHAR(MAX(PART_COST_USD)), '(null)') AS "max|PART_COST_USD",
    COALESCE(TO_VARCHAR(COUNT_IF(PART_COST_USD < 0)), '(null)') AS "negative_rows|PART_COST_USD",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(DEALER_CODE IS NULL OR TRIM(DEALER_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|DEALER_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(PARTS_PRODUCT_CODE IS NULL OR TRIM(PARTS_PRODUCT_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|PARTS_PRODUCT_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(AMO_CODE IS NULL OR TRIM(AMO_CODE) = '')) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_or_blank_pct|AMO_CODE",
    COALESCE(TO_VARCHAR(ROUND(100 * (COUNT_IF(LAST_UPDATE_TIMESTAMP IS NULL)) / NULLIF(COUNT(*), 0), 2)), '(null)') AS "null_pct|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MIN(LAST_UPDATE_TIMESTAMP)), '(null)') AS "min|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(MAX(LAST_UPDATE_TIMESTAMP)), '(null)') AS "max|LAST_UPDATE_TIMESTAMP",
    COALESCE(TO_VARCHAR(DATEDIFF('hour', MAX(LAST_UPDATE_TIMESTAMP), CURRENT_TIMESTAMP())), '(null)') AS "hours_since_max|LAST_UPDATE_TIMESTAMP"
  FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITY_MAJORCLASS_SUBCATEGORY_PARTCOST_TABLE
) UNPIVOT (value FOR metric IN ("rows|*", "distinct_key|OPPORTUNITY_KEY+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE+PARTS_PRODUCT_CODE+AMO_CODE", "duplicate_key_rows|OPPORTUNITY_KEY+COMMERCIAL_GROUP_CODE+MAJOR_CLASS_CODE+PARTS_PRODUCT_CODE+AMO_CODE", "distinct_full_rows|*", "duplicate_full_rows|*", "null_or_blank_pct|OPPORTUNITY_KEY", "null_or_blank_pct|COMMERCIAL_GROUP_CODE", "null_or_blank_pct|MAJOR_CLASS_CODE", "null_pct|PART_COST", "min|PART_COST", "max|PART_COST", "negative_rows|PART_COST", "null_pct|PART_COST_USD", "min|PART_COST_USD", "max|PART_COST_USD", "negative_rows|PART_COST_USD", "null_or_blank_pct|DEALER_CODE", "null_or_blank_pct|PARTS_PRODUCT_CODE", "null_or_blank_pct|AMO_CODE", "null_pct|LAST_UPDATE_TIMESTAMP", "min|LAST_UPDATE_TIMESTAMP", "max|LAST_UPDATE_TIMESTAMP", "hours_since_max|LAST_UPDATE_TIMESTAMP"));

-- Q11  Monthly volume of the telemetry tables by event time (gaps and coverage). NULL month = text that did not convert.
SELECT table_name, month, rows_, assets FROM (
  SELECT 'FAULT_CODE_BASIC_DAILY' AS table_name, DATE_TRUNC('month', TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)))::DATE AS month,
         COUNT(*) AS rows_, COUNT(DISTINCT ASSET_SERIAL_NUMBER) AS assets
  FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY GROUP BY 1, 2
  UNION ALL
  SELECT 'FAULT_CODE_HISTORY', DATE_TRUNC('month', TRY_TO_TIMESTAMP_NTZ(TRIM(OCCURRENCE_DATETIME)))::DATE, COUNT(*), COUNT(DISTINCT ASSET_SERIAL_NUMBER)
  FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_HISTORY GROUP BY 1, 2
  UNION ALL
  SELECT 'TELEMETRY_FUEL_BASIC_DAILY', DATE_TRUNC('month', TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))::DATE, COUNT(*), COUNT(DISTINCT ASSET_SERIAL_NUMBER)
  FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY GROUP BY 1, 2
  UNION ALL
  SELECT 'TELEMETRY_SMU_LOCATION_BASIC_DAILY', DATE_TRUNC('month', TRY_TO_TIMESTAMP_NTZ(TRIM(RECEIVED_DATETIME)))::DATE, COUNT(*), COUNT(DISTINCT ASSET_SERIAL_NUMBER)
  FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2
)
ORDER BY table_name, month;

-- Q12  OLGA snapshots: rows, serials and value per snapshot (decides how KPIs avoid double counting).
SELECT * FROM (
  SELECT 'CUSTOMER_TOTALS_TABLE' AS table_name, END_OF_MONTH AS snapshot, COUNT(*) AS rows_,
         NULL::NUMBER AS serials, ROUND(SUM(ENGINE_OPPORTUNITY + UNDERCARRIAGE_OPPORTUNITY + GET_OPPORTUNITY
           + DRIVETRAIN_OPPORTUNITY + HYDRAULICS_OPPORTUNITY + FLUIDSFILTERS_OPPORTUNITY + MAINTENANCE_OPPORTUNITY
           + STRUCTURAL_OPPORTUNITY + UNKNOWN_OPPORTUNITY)) AS value_sum, 'sum of *_OPPORTUNITY' AS value_meaning
  FROM SERVICE_INTELLIGENCE.OLGA.CUSTOMER_TOTALS_TABLE GROUP BY 1, 2
  UNION ALL
  SELECT 'OPPORTUNITIES_TABLE', END_OF_MONTH, COUNT(*), COUNT(DISTINCT SERIAL_NUMBER), ROUND(SUM(TOTAL_VALUE)), 'sum of TOTAL_VALUE'
  FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2
  UNION ALL
  SELECT 'LOST_OPPORTUNITY_REPORT_TABLE', YEAR_MONTH, COUNT(*), COUNT(DISTINCT SERIAL_NUMBER), ROUND(SUM(LOST_OPPORTUNITY_SCP)), 'sum of LOST_OPPORTUNITY_SCP'
  FROM SERVICE_INTELLIGENCE.OLGA.LOST_OPPORTUNITY_REPORT_TABLE GROUP BY 1, 2
  UNION ALL
  SELECT 'EQUIPMENT_REPORT_DETAIL_TABLE', '(no snapshot column)', COUNT(*), COUNT(DISTINCT SERIAL_NUMBER), ROUND(SUM(TOTAL_OPPORTUNITY_FUTURE_12_MONTHS)), 'sum of TOTAL_OPPORTUNITY_FUTURE_12_MONTHS'
  FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2
  UNION ALL
  SELECT 'COMPANY_CONFIG_TABLE', GENERATION_TIME, COUNT(*), NULL, NULL, NULL
  FROM SERVICE_INTELLIGENCE.OLGA.COMPANY_CONFIG_TABLE GROUP BY 1, 2
)
ORDER BY table_name, snapshot;

-- Q13  Value counts of low-cardinality columns (units, flags, levels, dealer codes). Top 25 per column.
SELECT table_name, column_name, value_, rows_,
       ROUND(100 * RATIO_TO_REPORT(rows_) OVER (PARTITION BY table_name, column_name), 2) AS pct
FROM (
  SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY' AS table_name, 'LEVEL' AS column_name, TO_VARCHAR(LEVEL) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY' AS table_name, 'STANDARD_MANUFACTURER_CODE' AS column_name, TO_VARCHAR(STANDARD_MANUFACTURER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY' AS table_name, 'FAULT_TYPE_CODE' AS column_name, TO_VARCHAR(FAULT_TYPE_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
