  SELECT 'DOMAIN_TELEMETRY.FAULT_CODE_HISTORY' AS table_name, 'PRODUCT_FAMILY_DESCRIPTION' AS column_name, TO_VARCHAR(PRODUCT_FAMILY_DESCRIPTION) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_HISTORY GROUP BY 1, 2, 3
