  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY' AS table_name, 'CUMULATIVE_FUEL_UOM' AS column_name, TO_VARCHAR(CUMULATIVE_FUEL_UOM) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY' AS table_name, 'IDLE_FUEL_UOM' AS column_name, TO_VARCHAR(IDLE_FUEL_UOM) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name, 'SERVICE_METER_UOM' AS column_name, TO_VARCHAR(SERVICE_METER_UOM) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name, 'IDLE_SERVICE_METER_UOM' AS column_name, TO_VARCHAR(IDLE_SERVICE_METER_UOM) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name, 'DISTANCE_TRAVELED_UOM' AS column_name, TO_VARCHAR(DISTANCE_TRAVELED_UOM) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name, 'VALID_FLAG' AS column_name, TO_VARCHAR(VALID_FLAG) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'CURRENT_EQUIPMENT' AS column_name, TO_VARCHAR(CURRENT_EQUIPMENT) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'INCLUDED_EXCLUDED' AS column_name, TO_VARCHAR(INCLUDED_EXCLUDED) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'PARKED_STATUS' AS column_name, TO_VARCHAR(PARKED_STATUS) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'CONNECTED_ASSET' AS column_name, TO_VARCHAR(CONNECTED_ASSET) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'UTILIZATION_TYPE' AS column_name, TO_VARCHAR(UTILIZATION_TYPE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'SMU_TYPE' AS column_name, TO_VARCHAR(SMU_TYPE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'DUPLICATE_SERIAL_NUMBER' AS column_name, TO_VARCHAR(DUPLICATE_SERIAL_NUMBER) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'PRODUCT_FAMILY_DESC' AS column_name, TO_VARCHAR(PRODUCT_FAMILY_DESC) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.EQUIPMENT_REPORT_DETAIL_TABLE' AS table_name, 'CONTRACT' AS column_name, TO_VARCHAR(CONTRACT) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE GROUP BY 1, 2, 3
