  SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name, 'OPPORTUNITY_SOURCE' AS column_name, TO_VARCHAR(OPPORTUNITY_SOURCE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name, 'CONNECTED_ASSET' AS column_name, TO_VARCHAR(CONNECTED_ASSET) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name, 'CONTRACT' AS column_name, TO_VARCHAR(CONTRACT) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2, 3
