  SELECT 'OLGA.OPPORTUNITIES_TABLE' AS table_name, 'BRANCH_DESC' AS column_name, TO_VARCHAR(BRANCH_DESC) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.LOST_OPPORTUNITY_REPORT_TABLE' AS table_name, 'DEALER_CODE' AS column_name, TO_VARCHAR(DEALER_CODE) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.LOST_OPPORTUNITY_REPORT_TABLE GROUP BY 1, 2, 3
  UNION ALL
  SELECT 'OLGA.LOST_OPPORTUNITY_REPORT_TABLE' AS table_name, 'BRANCH_DESCRIPTION' AS column_name, TO_VARCHAR(BRANCH_DESCRIPTION) AS value_, COUNT(*) AS rows_ FROM SERVICE_INTELLIGENCE.OLGA.LOST_OPPORTUNITY_REPORT_TABLE GROUP BY 1, 2, 3
