-- Q14  Serial-number match rates (distinct serials) between telemetry, OLGA and Helios service orders.
--      pct_a_matched = share of A's serials found in B. Two key forms: exact, and letters/digits only.
WITH
  TEL AS (
    SELECT UPPER(TRIM(ASSET_SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(ASSET_SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY WHERE NULLIF(TRIM(ASSET_SERIAL_NUMBER), '') IS NOT NULL
    UNION
    SELECT UPPER(TRIM(ASSET_SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(ASSET_SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_HISTORY WHERE NULLIF(TRIM(ASSET_SERIAL_NUMBER), '') IS NOT NULL
    UNION
    SELECT UPPER(TRIM(ASSET_SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(ASSET_SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY WHERE NULLIF(TRIM(ASSET_SERIAL_NUMBER), '') IS NOT NULL
    UNION
    SELECT UPPER(TRIM(ASSET_SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(ASSET_SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY WHERE NULLIF(TRIM(ASSET_SERIAL_NUMBER), '') IS NOT NULL
  ),
  OLGA_EQ AS (
    SELECT UPPER(TRIM(SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE WHERE NULLIF(TRIM(SERIAL_NUMBER), '') IS NOT NULL
  ),
  OLGA_OPP AS (
    SELECT UPPER(TRIM(SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE WHERE NULLIF(TRIM(SERIAL_NUMBER), '') IS NOT NULL
  ),
  OLGA_LOST AS (
    SELECT UPPER(TRIM(SERIAL_NUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(SERIAL_NUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM SERVICE_INTELLIGENCE.OLGA.LOST_OPPORTUNITY_REPORT_TABLE WHERE NULLIF(TRIM(SERIAL_NUMBER), '') IS NOT NULL
  ),
  SO_SERIAL AS (
    SELECT UPPER(TRIM(SERIALNUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(SERIALNUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER WHERE NULLIF(TRIM(SERIALNUMBER), '') IS NOT NULL AND ROWOPERATION <> 'DELETE'
  ),
  SO_DEVICE AS (
    SELECT UPPER(TRIM(DEVICENUMBER)) AS sn, NULLIF(REGEXP_REPLACE(UPPER(DEVICENUMBER), '[^A-Z0-9]', ''), '') AS sn_norm FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER WHERE NULLIF(TRIM(DEVICENUMBER), '') IS NOT NULL AND ROWOPERATION <> 'DELETE'
  ),
  pairs AS (
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA equipment' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM TEL x JOIN OLGA_EQ y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA equipment' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM TEL x JOIN OLGA_EQ y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA opportunities' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_OPP) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM TEL x JOIN OLGA_OPP y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA opportunities' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_OPP) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM TEL x JOIN OLGA_OPP y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA lost opportunity' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_LOST) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM TEL x JOIN OLGA_LOST y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'telemetry (4 tables)' AS source_a, 'OLGA lost opportunity' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM TEL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_LOST) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM TEL x JOIN OLGA_LOST y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'OLGA opportunities' AS source_a, 'OLGA equipment' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_OPP) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM OLGA_OPP x JOIN OLGA_EQ y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'OLGA opportunities' AS source_a, 'OLGA equipment' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_OPP) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM OLGA_OPP x JOIN OLGA_EQ y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'OLGA lost opportunity' AS source_a, 'OLGA equipment' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_LOST) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM OLGA_LOST x JOIN OLGA_EQ y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'OLGA lost opportunity' AS source_a, 'OLGA equipment' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_LOST) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM OLGA_LOST x JOIN OLGA_EQ y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.SERIALNUMBER' AS source_a, 'telemetry (4 tables)' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM SO_SERIAL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM TEL) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM SO_SERIAL x JOIN TEL y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.SERIALNUMBER' AS source_a, 'telemetry (4 tables)' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM SO_SERIAL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM TEL) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM SO_SERIAL x JOIN TEL y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.SERIALNUMBER' AS source_a, 'OLGA equipment' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM SO_SERIAL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM SO_SERIAL x JOIN OLGA_EQ y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.SERIALNUMBER' AS source_a, 'OLGA equipment' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM SO_SERIAL) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM SO_SERIAL x JOIN OLGA_EQ y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.DEVICENUMBER' AS source_a, 'telemetry (4 tables)' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM SO_DEVICE) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM TEL) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM SO_DEVICE x JOIN TEL y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.DEVICENUMBER' AS source_a, 'telemetry (4 tables)' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM SO_DEVICE) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM TEL) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM SO_DEVICE x JOIN TEL y ON x.sn_norm = y.sn_norm) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.DEVICENUMBER' AS source_a, 'OLGA equipment' AS source_b, 'exact (upper/trim)' AS key_form,
         (SELECT COUNT(DISTINCT sn) FROM SO_DEVICE) AS distinct_a,
         (SELECT COUNT(DISTINCT sn) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn) FROM SO_DEVICE x JOIN OLGA_EQ y ON x.sn = y.sn) AS matched
  UNION ALL
  SELECT 'SERVICEORDER.DEVICENUMBER' AS source_a, 'OLGA equipment' AS source_b, 'alphanumeric only' AS key_form,
         (SELECT COUNT(DISTINCT sn_norm) FROM SO_DEVICE) AS distinct_a,
         (SELECT COUNT(DISTINCT sn_norm) FROM OLGA_EQ) AS distinct_b,
         (SELECT COUNT(DISTINCT x.sn_norm) FROM SO_DEVICE x JOIN OLGA_EQ y ON x.sn_norm = y.sn_norm) AS matched
  )
SELECT source_a, source_b, key_form, distinct_a, distinct_b, matched,
       ROUND(100 * matched / NULLIF(distinct_a, 0), 2) AS pct_a_matched,
       ROUND(100 * matched / NULLIF(distinct_b, 0), 2) AS pct_b_matched
FROM pairs
ORDER BY source_a, source_b, key_form;

-- Q15  Other join keys: dealer codes, customer identifiers, opportunity keys (distinct values and matches).
WITH
  tel_dealer AS (SELECT DISTINCT TRIM(DEALER_CODE) k FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.FAULT_CODE_BASIC_DAILY
                 UNION SELECT TRIM(DEALER_CODE) FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY
                 UNION SELECT TRIM(DEALER_CODE) FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_FUEL_BASIC_DAILY),
  olga_dealer AS (SELECT DISTINCT TRIM(DEALER_CODE) k FROM SERVICE_INTELLIGENCE.OLGA.COMPANY_CONFIG_TABLE),
  tel_cust AS (SELECT DISTINCT UPPER(TRIM(PRIMARY_CUSTOMER_IDENTIFIER)) k FROM SERVICE_INTELLIGENCE.DOMAIN_TELEMETRY.TELEMETRY_SMU_LOCATION_BASIC_DAILY
               WHERE NULLIF(TRIM(PRIMARY_CUSTOMER_IDENTIFIER), '') IS NOT NULL),
  olga_cust AS (SELECT DISTINCT UPPER(TRIM(CUSTOMER_NUMBER)) k FROM SERVICE_INTELLIGENCE.OLGA.EQUIPMENT_REPORT_DETAIL_TABLE
                WHERE NULLIF(TRIM(CUSTOMER_NUMBER), '') IS NOT NULL),
  opp_key AS (SELECT DISTINCT OPPORTUNITY_KEY k FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITIES_TABLE WHERE OPPORTUNITY_KEY IS NOT NULL),
  cost_key AS (SELECT DISTINCT OPPORTUNITY_KEY k FROM SERVICE_INTELLIGENCE.OLGA.OPPORTUNITY_MAJORCLASS_SUBCATEGORY_PARTCOST_TABLE WHERE OPPORTUNITY_KEY IS NOT NULL)
SELECT 'dealer: telemetry -> OLGA COMPANY_CONFIG' AS key_check, (SELECT COUNT(*) FROM tel_dealer) AS distinct_a,
       (SELECT COUNT(*) FROM olga_dealer) AS distinct_b, (SELECT COUNT(*) FROM tel_dealer JOIN olga_dealer USING (k)) AS matched
UNION ALL
SELECT 'customer: telemetry PRIMARY_CUSTOMER_IDENTIFIER -> OLGA equipment CUSTOMER_NUMBER', (SELECT COUNT(*) FROM tel_cust),
       (SELECT COUNT(*) FROM olga_cust), (SELECT COUNT(*) FROM tel_cust JOIN olga_cust USING (k))
UNION ALL
SELECT 'opportunity: part-cost OPPORTUNITY_KEY -> OPPORTUNITIES_TABLE', (SELECT COUNT(*) FROM cost_key),
       (SELECT COUNT(*) FROM opp_key), (SELECT COUNT(*) FROM cost_key JOIN opp_key USING (k));

-- Q16  Helios service orders (MANDL_CDM_PROD.MANCDM.SERVICEORDER): coverage, freshness, nulls, duplicates.
SELECT check_name, value FROM (
  SELECT
    TO_VARCHAR(COUNT(*)) AS "rows",
    TO_VARCHAR(COUNT(DISTINCT SERVICEORDERID)) AS "distinct_serviceorderid",
    TO_VARCHAR(COUNT_IF(ROWOPERATION = 'DELETE')) AS "soft_deleted_rows",
    TO_VARCHAR(COUNT(DISTINCT SERVICEORDERNUMBER)) AS "distinct_serviceordernumber",
    TO_VARCHAR(MIN(OPENDATE)) AS "opendate_min",
    TO_VARCHAR(MAX(OPENDATE)) AS "opendate_max",
    TO_VARCHAR(COUNT_IF(OPENDATE >= DATEADD('month', -24, CURRENT_DATE()))) AS "rows_opened_last_24_months",
    TO_VARCHAR(MAX(LASTUPDATEDDATETIME)) AS "lastupdateddatetime_max",
    TO_VARCHAR(MAX(MODIFIEDON)) AS "modifiedon_max",
    TO_VARCHAR(ROUND(100 * COUNT_IF(OPENDATE IS NULL) / COUNT(*), 2)) AS "opendate_null_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(LASTCLOSEDATE IS NULL) / COUNT(*), 2)) AS "lastclosedate_null_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(FINISHEDDATE IS NULL) / COUNT(*), 2)) AS "finisheddate_null_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(PROMISEDENDDATE IS NULL) / COUNT(*), 2)) AS "promisedenddate_null_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(FIRSTLABORDATE IS NULL) / COUNT(*), 2)) AS "firstlabordate_null_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(NULLIF(TRIM(SERIALNUMBER), '') IS NULL) / COUNT(*), 2)) AS "serialnumber_null_or_blank_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(NULLIF(TRIM(SERVICEORDERPRIORITY), '') IS NULL) / COUNT(*), 2)) AS "priority_null_or_blank_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(NULLIF(TRIM(REPAIRTYPE), '') IS NULL) / COUNT(*), 2)) AS "repairtype_null_or_blank_pct",
    TO_VARCHAR(ROUND(100 * COUNT_IF(NULLIF(TRIM(STORECODE), '') IS NULL) / COUNT(*), 2)) AS "storecode_null_or_blank_pct",
    TO_VARCHAR(COUNT_IF(LASTCLOSEDATE < OPENDATE)) AS "close_before_open_rows",
    TO_VARCHAR(COUNT_IF(FINISHEDDATE < OPENDATE)) AS "finished_before_open_rows",
    TO_VARCHAR(COUNT_IF(ISOPEN)) AS "isopen_true_rows",
    TO_VARCHAR(COUNT_IF(ISOPEN AND OPENDATE < DATEADD('day', -30, CURRENT_DATE()))) AS "open_older_than_30d_rows",
    TO_VARCHAR(COUNT_IF(LASTCLOSEDATE IS NOT NULL AND PROMISEDENDDATE IS NOT NULL)) AS "closed_with_promise_rows",
    TO_VARCHAR(COUNT_IF(LASTCLOSEDATE IS NOT NULL AND PROMISEDENDDATE IS NOT NULL AND LASTCLOSEDATE <= PROMISEDENDDATE)) AS "closed_on_or_before_promise_rows",
    TO_VARCHAR(MEDIAN(DATEDIFF('day', OPENDATE, LASTCLOSEDATE))) AS "median_days_open_to_close",
    TO_VARCHAR(COUNT(DISTINCT ROWOPERATION)) AS "distinct_rowoperation"
  FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER
) UNPIVOT (value FOR check_name IN ("rows", "distinct_serviceorderid", "soft_deleted_rows", "distinct_serviceordernumber", "opendate_min",
  "opendate_max", "rows_opened_last_24_months", "lastupdateddatetime_max", "modifiedon_max", "opendate_null_pct",
  "lastclosedate_null_pct", "finisheddate_null_pct", "promisedenddate_null_pct", "firstlabordate_null_pct",
  "serialnumber_null_or_blank_pct", "priority_null_or_blank_pct", "repairtype_null_or_blank_pct",
  "storecode_null_or_blank_pct", "close_before_open_rows", "finished_before_open_rows", "isopen_true_rows",
  "open_older_than_30d_rows", "closed_with_promise_rows", "closed_on_or_before_promise_rows",
  "median_days_open_to_close", "distinct_rowoperation"));

-- Q17  Helios service orders: status, open status, repair type, priority, source and row operation values.
SELECT column_name, value_, rows_ FROM (
  SELECT 'SERVICEORDERSTATUS' AS column_name, TO_VARCHAR(SERVICEORDERSTATUS) AS value_, COUNT(*) AS rows_ FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'STDSERVICEORDEROPENSTATUS_DISPLAY', STDSERVICEORDEROPENSTATUS_DISPLAY, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'SERVICEORDEROPENSTATUS_DISPLAY', SERVICEORDEROPENSTATUS_DISPLAY, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'STATECODE_DISPLAY', STATECODE_DISPLAY, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'REPAIRTYPE_DISPLAY', REPAIRTYPE_DISPLAY, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'SERVICEORDERPRIORITY', SERVICEORDERPRIORITY, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'SERVICEORDERTYPE', SERVICEORDERTYPE, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'DEVICEBRANDCODE', DEVICEBRANDCODE, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'SOURCE', SOURCE, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'ROWOPERATION', ROWOPERATION, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
  UNION ALL SELECT 'DIVISIONCODE', DIVISIONCODE, COUNT(*) FROM MANDL_CDM_PROD.MANCDM.SERVICEORDER GROUP BY 1, 2
)
QUALIFY ROW_NUMBER() OVER (PARTITION BY column_name ORDER BY rows_ DESC) <= 25
ORDER BY column_name, rows_ DESC;
